36:   // static struct aligned_buffer In __attribute__((aligned(PG_SIZE)));
37:   static struct offset_buffer In __attribute__((aligned(PG_SIZE)));
38:   static struct offset_buffer Out __attribute__((aligned(PG_SIZE)));
39: 
40:   for (size_t i = 0; i < OFFSET; ++i) {
41:       In.garbage[i] = ~0;
42:       Out.garbage[i] = 1;
43:   }
44: 
45:   for (size_t i = 0; i < DIM; ++i)
46:     for (size_t j = 0; j < DIM; ++j) {
47:       In.data[i][j] = i*DIM + j;
48:       Out.data[i][j] = 1;
49:     }
50: 
51:   gemmini_config_ld(DIM * sizeof(elem_t));
52:   gemmini_config_st(DIM * sizeof(elem_t));
53: 
54:   // printf("Mvin\n");
55:   gemmini_mvin(In.data, 0);
56:   // printf("Mvout\n");
57:   gemmini_mvout(Out.data, 0);
58: 
