 14: #ifndef BAREMETAL
 15: 
 16: #define BATCH_SIZE 4
 17: #define IN_ROW_DIM 224
 18: #define IN_COL_DIM 224
 19: #define IN_CHANNELS 3
 20: #define OUT_CHANNELS 32
 21: #define KERNEL_DIM 3
 22: #define PADDING 1
 23: #define STRIDE 2
 24: 
 25: #else
 26: 
 27: #ifdef FAST
 28: 
 29: #define IN_ROW_DIM 9
 30: #define IN_COL_DIM 9
 31: #define IN_CHANNELS 3
 32: #define OUT_CHANNELS 7
 33: 
 34: #else
 35: 
 36: #define IN_ROW_DIM 17
 37: #define IN_COL_DIM 17
 38: #define IN_CHANNELS 3
 39: #define OUT_CHANNELS 19
 40: 
 41: #endif
 42: 
 43: #define BATCH_SIZE 2
 44: #define KERNEL_DIM 3
 45: #define PADDING 1
 46: #define STRIDE 2
 47: 
 48: #endif
 49: 
 50: #define NO_BIAS false
 51: 
 52: #define OUT_ROW_DIM ((IN_ROW_DIM + 2*PADDING - KERNEL_DIM) / STRIDE + 1)
 53: #define OUT_COL_DIM ((IN_COL_DIM + 2*PADDING - KERNEL_DIM) / STRIDE + 1)
 54: #define PATCH_SIZE (KERNEL_DIM * KERNEL_DIM * IN_CHANNELS)
 55: #define N_PATCHES (BATCH_SIZE * OUT_ROW_DIM * OUT_COL_DIM)
 56: 
 57: void conv(int batch_size, int in_channels,
 58:         int in_row_dim, int in_col_dim,
 59:         int out_channels, int kernel_dim,
 60:         int out_row_dim, int out_col_dim,
 61:         int stride, int padding,
 62:         elem_t input[batch_size][in_row_dim][in_col_dim][in_channels],
 63:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
 64:         acc_t bias[out_channels],
 65:         elem_t output[batch_size][out_row_dim][out_col_dim][out_channels]) {
 66: 
 67: #ifdef GEMMINI_ASSERTIONS
 68:     if (out_row_dim != (in_row_dim + 2*padding - kernel_dim) / stride + 1) {
 69:         printf("conv out_row_dim is not correct\n");
 70:         exit(1);
 71:     }
 72:     if (out_col_dim != (in_col_dim + 2*padding - kernel_dim) / stride + 1) {
 73:         printf("conv out_col_dim is not correct\n");
 74:         exit(1);
 75:     }
 76: #endif
 77: 
 78:     for (int b = 0; b < batch_size; b++) {
 79:         for (int orow = 0; orow < out_row_dim; orow++) {
 80:             for (int ocol = 0; ocol < out_col_dim; ocol++) {
 81:                 for (int och = 0; och < out_channels; och++) {
 82:                     acc_t result = bias[och];
 83: 
 84:                     for (int krow = 0; krow < kernel_dim; krow++) {
 85:                         for (int kcol = 0; kcol < kernel_dim; kcol++) {
 86:                             for (int kch = 0; kch < in_channels; kch++) {
 87:                                 int irow = orow * stride + krow - padding;
 88:                                 int icol = ocol * stride + kcol - padding;
 89: 
 90:                                 elem_t pixel = irow < 0 || irow >= in_row_dim ||
 91:                                     icol < 0 || icol >= in_col_dim ?
 92:                                     0 : input[b][irow][icol][kch];
 93: 
 94:                                 result +=
 95:                                     weights[och][krow][kcol][kch] *
 96:                                     pixel;
 97:                             }
 98:                         }
 99:                     }
100: 
101:                     // Clip result
102:                     result = result > elem_t_max ? elem_t_max : (result < elem_t_min ? elem_t_min : result);
103: 
104:                     output[b][orow][ocol][och] = result;
105:                 }
106:             }
107:         }
108:     }
109: }
110: 
111: void flatten_weights(int out_channels, int kernel_dim, int in_channels,
112:         int patch_size,
113:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
114:         elem_t weights_mat[patch_size][out_channels]) {
115: 
116:     assert(patch_size == kernel_dim * kernel_dim * in_channels);
117: 
118:     for (int outc = 0; outc < out_channels; outc++) {
119:         for (int krow = 0; krow < kernel_dim; krow++) {
120:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
121:                 for (int inc = 0; inc < in_channels; inc++) {
122:                     int wmatrow = krow * kernel_dim * in_channels +
123:                         kcol * in_channels +
124:                         inc;
125: 
126:                     weights_mat[wmatrow][outc] =
127:                         weights[outc][krow][kcol][inc];
128:                 }
129:             }
130:         }
131:     }
132: }
