 67: void conv(int batch_size, int in_channels,
 68:         int in_row_dim, int in_col_dim,
 69:         int out_channels, int kernel_dim,
 70:         int out_row_dim, int out_col_dim,
 71:         int stride, int padding,
 72:         elem_t input[batch_size][in_row_dim][in_col_dim][in_channels],
 73:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
 74:         acc_t bias[out_channels],
 75:         elem_t output[batch_size][out_row_dim][out_col_dim][out_channels]) {
 76: 
 77: #ifdef GEMMINI_ASSERTIONS
 78:     if (out_row_dim != (in_row_dim + 2 * padding - kernel_dim) / stride + 1) {
 79:         printf("conv out_row_dim is not correct\n");
 80:         exit(1);
 81:     }
 82:     if (out_col_dim != (in_col_dim + 2 * padding - kernel_dim) / stride + 1) {
 83:         printf("conv out_col_dim is not correct\n");
 84:         exit(1);
 85:     }
 86: #endif
 87: 
 88:     for (int b = 0; b < batch_size; b++) {
 89:         for (int orow = 0; orow < out_row_dim; orow++) {
 90:             for (int ocol = 0; ocol < out_col_dim; ocol++) {
 91:                 for (int och = 0; och < out_channels; och++) {
 92:                     acc_t result = bias[och];
 93: 
 94:                     for (int krow = 0; krow < kernel_dim; krow++) {
 95:                         for (int kcol = 0; kcol < kernel_dim; kcol++) {
 96:                             for (int kch = 0; kch < in_channels; kch++) {
 97:                                 int irow = orow * stride + krow - padding;
 98:                                 int icol = ocol * stride + kcol - padding;
 99: 
100:                                 elem_t pixel = irow < 0 || irow >= in_row_dim ||
101:                                     icol < 0 || icol >= in_col_dim ?
102:                                     0 : input[b][irow][icol][kch];
103: 
104:                                 result +=
105:                                     weights[och][krow][kcol][kch] *
106:                                     pixel;
107:                             }
108:                         }
109:                     }
110: 
111:                     // Clip result
112:                     result = result > elem_t_max ? elem_t_max : (result < elem_t_min ? elem_t_min : result);
113: 
114:                     output[b][orow][ocol][och] = result;
115:                 }
116:             }
117:         }
118:     }
119: }
120: 
121: void pool(int batch_size, int channels,
122:         int in_row_dim, int in_col_dim, int out_row_dim, int out_col_dim,
123:         int window_dim, int stride, int padding,
124:         elem_t input[batch_size][in_row_dim][in_col_dim][channels],
125:         elem_t output[batch_size][out_row_dim][out_col_dim][channels]) {
126: 
127:     for (int b = 0; b < batch_size; b++) {
128:         for (int orow = 0; orow < out_row_dim; orow++) {
129:             for (int ocol = 0; ocol < out_col_dim; ocol++) {
130:                 for (int ch = 0; ch < channels; ch++) {
131:                     output[b][orow][ocol][ch] = elem_t_min;
132: 
133:                     for (int wrow = 0; wrow < window_dim; wrow++) {
134:                         for (int wcol = 0; wcol < window_dim; wcol++) {
135:                             int irow = orow * stride + wrow - padding;
136:                             int icol = ocol * stride + wcol - padding;
137: 
138:                             elem_t pixel = irow < 0 || irow >= in_row_dim ||
139:                                 icol < 0 || icol >= in_col_dim ?
140:                                 0 : input[b][irow][icol][ch];
141: 
142:                             if (pixel > output[b][orow][ocol][ch]) {
143:                                 output[b][orow][ocol][ch] = pixel;
144:                             }
145:                         }
146:                     }
147:                 }
148:             }
149:         }
150:     }
151: }
152: 
153: void flatten_weights(int out_channels, int kernel_dim, int in_channels,
154:         int patch_size,
155:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
156:         elem_t weights_mat[patch_size][out_channels]) {
157: 
158:     assert(patch_size == kernel_dim * kernel_dim * in_channels);
159: 
160:     for (int outc = 0; outc < out_channels; outc++) {
161:         for (int krow = 0; krow < kernel_dim; krow++) {
162:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
163:                 for (int inc = 0; inc < in_channels; inc++) {
164:                     int wmatrow = krow * kernel_dim * in_channels +
165:                         kcol * in_channels +
166:                         inc;
167: 
168:                     weights_mat[wmatrow][outc] =
169:                         weights[outc][krow][kcol][inc];
170:                 }
171:             }
172:         }
173:     }
174: }
175: 
176: bool vec_is_equal(elem_t * a, elem_t * b, int len) {
177:     for (int i = 0; i < len; i++)
178:         if (a[i] != b[i])
179:             return false;
180:     return true;
181: }
