183: void init_random(elem_t * buf, int len) {
184:     elem_t i = 0;
185:     for (elem_t * ptr = buf; ptr < buf + len; ptr++) {
186:         // *ptr = (rand() % 32) - 16;
187: #ifdef FAST
188:       *ptr = 1;
189: #else
190:         *ptr = (rand() % 5) - 2;
191: #endif
192:     }
193: }
194: 
195: void init_random_acc(acc_t * buf, int len) {
196:     elem_t i = 0;
197:     for (acc_t * ptr = buf; ptr < buf + len; ptr++) {
198:         // *ptr = (rand() % 32) - 16;
199: #ifdef FAST
200:       *ptr = 1;
201: #else
202:         *ptr = (rand() % 5) - 2;
203: #endif
204:     }
205: }
206: 
207: void init_zeros_acc(acc_t * buf, int len) {
208:     for (acc_t * ptr = buf; ptr < buf + len; ptr++) {
209:         *ptr = 0;
210:     }
211: }
