109: void flatten_weights(int out_channels, int kernel_dim, int in_channels,
110:         int patch_size,
111:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
112:         elem_t weights_mat[patch_size][out_channels]) {
113: 
114:     assert(patch_size == kernel_dim * kernel_dim * in_channels);
115: 
116:     for (int outc = 0; outc < out_channels; outc++) {
117:         for (int krow = 0; krow < kernel_dim; krow++) {
118:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
119:                 for (int inc = 0; inc < in_channels; inc++) {
120:                     int wmatrow = krow * kernel_dim * in_channels +
121:                         kcol * in_channels +
122:                         inc;
123: 
124:                     weights_mat[wmatrow][outc] =
125:                         weights[outc][krow][kcol][inc];
126:                 }
127:             }
128:         }
129:     }
130: }
