132: void init_random(elem_t * buf, int row, int col, int stride){
133:     elem_t i = 0;
134:     for(int r = 0; r < row; r++){
135:         for(int c = 0; c < col; c++){
136:             elem_t * ptr = buf + r * stride + c;
137:             *ptr = (rand() % 5) - 2;
138:         }
139:     }
140: }
141: 
142: void init_random_acc(acc_t * buf, int len) {
143:     elem_t i = 0;
144:     for (acc_t * ptr = buf; ptr < buf + len; ptr++) {
145:         // *ptr = (rand() % 32) - 16;
146:       *ptr = (rand() % 5) - 2;
147:     }
148: }
149: 
150: void init_zeros_acc(acc_t * buf, int len) {
151:     for (acc_t * ptr = buf; ptr < buf + len; ptr++) {
152:         *ptr = 0;
153:     }
154: }
