 61: void flatten_weights(int out_channels, int kernel_dim, int in_channels,
 62:         int patch_size,
 63:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
 64:         elem_t weights_mat[patch_size][out_channels]) {
