 70:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
 71:                 for (int inc = 0; inc < in_channels; inc++) {
 72:                     int wmatrow = krow * kernel_dim * in_channels +
 73:                         kcol * in_channels +
 74:                         inc;
