 56: void flatten_weights(int out_channels, int kernel_dim, int in_channels,
 57:         int patch_size,
 58:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
 59:         elem_t weights_mat[patch_size][out_channels]) {
 60: 
 61:     assert(patch_size == kernel_dim * kernel_dim * in_channels);
 62: 
 63:     for (int outc = 0; outc < out_channels; outc++) {
 64:         for (int krow = 0; krow < kernel_dim; krow++) {
 65:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
 66:                 for (int inc = 0; inc < in_channels; inc++) {
 67:                     int wmatrow = krow * kernel_dim * in_channels +
 68:                         kcol * in_channels +
 69:                         inc;
 70: 
 71:                     weights_mat[wmatrow][outc] =
 72:                         weights[outc][krow][kcol][inc];
 73:                 }
 74:             }
 75:         }
 76:     }
 77: }
