 57: void flatten_weights(int out_channels, int kernel_dim, int in_channels,
 58:         int patch_size,
 59:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
 60:         elem_t weights_mat[patch_size][out_channels]) {
 61: 
 62:     assert(patch_size == kernel_dim * kernel_dim * in_channels);
 63: 
 64:     for (int outc = 0; outc < out_channels; outc++) {
 65:         for (int krow = 0; krow < kernel_dim; krow++) {
 66:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
 67:                 for (int inc = 0; inc < in_channels; inc++) {
 68:                     int wmatrow = krow * kernel_dim * in_channels +
 69:                         kcol * in_channels +
 70:                         inc;
 71: 
 72:                     weights_mat[wmatrow][outc] =
 73:                         weights[outc][krow][kcol][inc];
 74:                 }
 75:             }
 76:         }
 77:     }
 78: }
