 99: void init_random_acc(acc_t * buf, int len) {
100:     elem_t i = 0;
101:     for (acc_t * ptr = buf; ptr < buf + len; ptr++) {
102:         // *ptr = (rand() % 32) - 16;
103: #ifdef FAST
104:       *ptr = 1;
105: #else
106:       *ptr = (rand() % 5) - 2;
107: #endif
108:     }
109: }
110: 
111: void init_zeros_acc(acc_t * buf, int len) {
112:     for (acc_t * ptr = buf; ptr < buf + len; ptr++) {
113:         *ptr = 0;
114:     }
115: }
