 12: 
 13: #define BATCH_SIZE 4
 14: #define IN_ROW_DIM 224
 15: #define IN_COL_DIM 224
 16: #define IN_CHANNELS 3
 17: #define OUT_CHANNELS 17
 18: #define KERNEL_DIM 3
 19: #define PADDING -1
 20: #define STRIDE 1
 21: #define INPUT_DILATION 2
 22: 
