 47: #endif
 48: 
 49: #define NO_BIAS false
 50: 
 51: #define IN_ROW_DIM_DILATED (IN_ROW_DIM + (INPUT_DILATION - 1)*(IN_ROW_DIM - 1))
 52: #define IN_COL_DIM_DILATED (IN_COL_DIM + (INPUT_DILATION - 1)*(IN_COL_DIM - 1))
 53: #define OUT_ROW_DIM ((IN_ROW_DIM_DILATED + 2*PADDING - KERNEL_DIM) / STRIDE + 1)
 54: #define OUT_COL_DIM ((IN_COL_DIM_DILATED + 2*PADDING - KERNEL_DIM) / STRIDE + 1)
 55: #define PATCH_SIZE (KERNEL_DIM * KERNEL_DIM * IN_CHANNELS)
 56: #define N_PATCHES (BATCH_SIZE * OUT_ROW_DIM * OUT_COL_DIM)
 57: 
 58: void conv(int batch_size, int in_channels,
 59:         int in_row_dim, int in_col_dim,
 60:         int out_channels, int kernel_dim,
 61:         int out_row_dim, int out_col_dim,
 62:         int stride, int input_dilation, int padding,
 63:         elem_t input[batch_size][in_row_dim][in_col_dim][in_channels],
 64:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
 65:         acc_t bias[out_channels],
 66:         elem_t output[batch_size][out_row_dim][out_col_dim][out_channels]) {
 67: 
 68:     const size_t in_row_dim_dilated = in_row_dim + (input_dilation - 1)*(in_row_dim - 1);
 69:     const size_t in_col_dim_dilated = in_col_dim + (input_dilation - 1)*(in_col_dim - 1);
 70:     assert(in_row_dim_dilated == IN_ROW_DIM_DILATED);
 71:     assert(in_col_dim_dilated == IN_COL_DIM_DILATED);
 72:     static elem_t dilated[BATCH_SIZE][IN_ROW_DIM_DILATED][IN_COL_DIM_DILATED][IN_CHANNELS];
 73: 
 74: #ifdef GEMMINI_ASSERTIONS
 75:     if (out_row_dim != (in_row_dim_dilated + 2*padding - kernel_dim) / stride + 1) {
 76:         printf("conv out_row_dim is not correct\n");
 77:         printf("out_row_dim\n");
 78:         exit(1);
 79:     }
 80:     if (out_col_dim != (in_col_dim_dilated + 2*padding - kernel_dim) / stride + 1) {
 81:         printf("conv out_col_dim is not correct\n");
 82:         printf("out_col_dim\n");
 83:         exit(1);
 84:     }
 85: #endif
 86: 
 87:     for (int b = 0; b < batch_size; b++)
 88:         for (int irow = 0; irow < in_row_dim_dilated; irow++)
 89:             for (int icol = 0; icol < in_col_dim_dilated; icol++)
 90:                 for (int ich = 0; ich < in_channels; ich++)
 91:                     dilated[b][irow][icol][ich] = 0;
 92: 
 93:     size_t idx = 0;
 94:     for (int b = 0; b < batch_size; b++)
 95:         for (int irow = 0; irow < in_row_dim_dilated; irow += input_dilation)
 96:             for (int icol = 0; icol < in_col_dim_dilated; icol += input_dilation)
 97:                 for (int ich = 0; ich < in_channels; ich++) {
 98:                     dilated[b][irow][icol][ich] = *((elem_t*)input + idx);
 99:                     idx++;
100:                 }
101: 
102:     for (int b = 0; b < batch_size; b++) {
103:         for (int orow = 0; orow < out_row_dim; orow++) {
104:             for (int ocol = 0; ocol < out_col_dim; ocol++) {
105:                 for (int och = 0; och < out_channels; och++) {
106:                     acc_t result = bias[och];
107: 
108:                     for (int krow = 0; krow < kernel_dim; krow++) {
109:                         for (int kcol = 0; kcol < kernel_dim; kcol++) {
110:                             for (int kch = 0; kch < in_channels; kch++) {
111:                                 int irow = orow * stride + krow - padding;
112:                                 int icol = ocol * stride + kcol - padding;
113: 
114:                                 elem_t pixel = irow < 0 || irow >= in_row_dim_dilated ||
115:                                     icol < 0 || icol >= in_col_dim_dilated ?
116:                                     0 : dilated[b][irow][icol][kch];
117: 
118:                                 result +=
119:                                     weights[och][krow][kcol][kch] *
120:                                     pixel;
121:                             }
122:                         }
123:                     }
124: 
125:                     // Clip result
126:                     result = result > elem_t_max ? elem_t_max : (result < elem_t_min ? elem_t_min : result);
127: 
128:                     output[b][orow][ocol][och] = result;
129:                 }
130:             }
131:         }
132:     }
133: }
