135: void flatten_weights(int out_channels, int kernel_dim, int in_channels,
136:         int patch_size,
137:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
138:         elem_t weights_mat[patch_size][out_channels]) {
139: 
140:     assert(patch_size == kernel_dim * kernel_dim * in_channels);
141: 
142:     for (int outc = 0; outc < out_channels; outc++) {
143:         for (int krow = 0; krow < kernel_dim; krow++) {
144:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
145:                 for (int inc = 0; inc < in_channels; inc++) {
146:                     int wmatrow = krow * kernel_dim * in_channels +
147:                         kcol * in_channels +
148:                         inc;
149: 
150:                     weights_mat[wmatrow][outc] =
151:                         weights[outc][krow][kcol][inc];
152:                 }
153:             }
154:         }
155:     }
156: }
