 17: #define OUT_CHANNELS 17
 18: #define KERNEL_DIM 3
 19: #define PADDING 1
 20: #define STRIDE 1
 21: #define INPUT_DILATION 2
 22: 
 23: #else
 24: 
 25: #ifdef FAST
 26: 
 27: #define IN_ROW_DIM 9
 28: #define IN_COL_DIM 9
 29: #define IN_CHANNELS 5
 30: #define OUT_CHANNELS 7
 31: 
 32: #else
 33: 
 34: #define IN_ROW_DIM 17
