 36: #define IN_CHANNELS 18
 37: #define OUT_CHANNELS 19
 38: 
 39: #endif
 40: 
 41: #define BATCH_SIZE 2
 42: #define KERNEL_DIM 3
 43: #define PADDING 1
 44: #define STRIDE 1
 45: #define INPUT_DILATION 2
 46: 
 47: #endif
 48: 
 49: #define NO_BIAS false
 50: 
 51: #define WROT180 true
 52: 
 53: #define IN_ROW_DIM_DILATED (IN_ROW_DIM + (INPUT_DILATION - 1)*(IN_ROW_DIM - 1))
 54: #define IN_COL_DIM_DILATED (IN_COL_DIM + (INPUT_DILATION - 1)*(IN_COL_DIM - 1))
 55: #define OUT_ROW_DIM ((IN_ROW_DIM_DILATED + 2*PADDING - KERNEL_DIM) / STRIDE + 1)
 56: #define OUT_COL_DIM ((IN_COL_DIM_DILATED + 2*PADDING - KERNEL_DIM) / STRIDE + 1)
 57: #define PATCH_SIZE (KERNEL_DIM * KERNEL_DIM * IN_CHANNELS)
 58: #define N_PATCHES (BATCH_SIZE * OUT_ROW_DIM * OUT_COL_DIM)
 59: 
 60: void conv(int batch_size, int in_channels,
 61:         int in_row_dim, int in_col_dim,
 62:         int out_channels, int kernel_dim,
 63:         int out_row_dim, int out_col_dim,
 64:         int stride, int input_dilation, int padding, bool wrot180,
 65:         elem_t input[batch_size][in_row_dim][in_col_dim][in_channels],
 66:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
 67:         acc_t bias[out_channels],
 68:         elem_t output[batch_size][out_row_dim][out_col_dim][out_channels]) {
 69: 
 70:     const size_t in_row_dim_dilated = in_row_dim + (input_dilation - 1)*(in_row_dim - 1);
 71:     const size_t in_col_dim_dilated = in_col_dim + (input_dilation - 1)*(in_col_dim - 1);
 72:     assert(in_row_dim_dilated == IN_ROW_DIM_DILATED);
 73:     assert(in_col_dim_dilated == IN_COL_DIM_DILATED);
 74:     static elem_t dilated[BATCH_SIZE][IN_ROW_DIM_DILATED][IN_COL_DIM_DILATED][IN_CHANNELS];
 75: 
 76:     static elem_t weights_rot180[OUT_CHANNELS][KERNEL_DIM][KERNEL_DIM][IN_CHANNELS];
 77: 
 78: #ifdef GEMMINI_ASSERTIONS
 79:     if (out_row_dim != (in_row_dim_dilated + 2*padding - kernel_dim) / stride + 1) {
 80:         printf("conv out_row_dim is not correct\n");
 81:         printf("out_row_dim\n");
 82:         exit(1);
 83:     }
 84:     if (out_col_dim != (in_col_dim_dilated + 2*padding - kernel_dim) / stride + 1) {
 85:         printf("conv out_col_dim is not correct\n");
 86:         printf("out_col_dim\n");
 87:         exit(1);
 88:     }
 89: #endif
 90: 
 91:     // Populate dilated
 92:     for (int b = 0; b < batch_size; b++)
 93:         for (int irow = 0; irow < in_row_dim_dilated; irow++)
 94:             for (int icol = 0; icol < in_col_dim_dilated; icol++)
 95:                 for (int ich = 0; ich < in_channels; ich++)
 96:                     dilated[b][irow][icol][ich] = 0;
 97: 
 98:     size_t idx = 0;
 99:     for (int b = 0; b < batch_size; b++)
100:         for (int irow = 0; irow < in_row_dim_dilated; irow += input_dilation)
101:             for (int icol = 0; icol < in_col_dim_dilated; icol += input_dilation)
102:                 for (int ich = 0; ich < in_channels; ich++) {
103:                     dilated[b][irow][icol][ich] = *((elem_t*)input + idx);
104:                     idx++;
105:                 }
106: 
107:     // Populate weights_rot180
108:     for (int och = 0; och < out_channels; och++)
109:         for (int krow = 0; krow < kernel_dim; krow++)
110:             for (int kcol = 0; kcol < kernel_dim; kcol++)
111:                 for (int kch = 0; kch < in_channels; kch++)
112:                     weights_rot180[och][krow][kcol][kch] =
113:                         weights[och][kernel_dim-krow-1][kernel_dim-kcol-1][kch];
114: 
115:     for (int b = 0; b < batch_size; b++) {
116:         for (int orow = 0; orow < out_row_dim; orow++) {
117:             for (int ocol = 0; ocol < out_col_dim; ocol++) {
118:                 for (int och = 0; och < out_channels; och++) {
119:                     acc_t result = bias[och];
120: 
121:                     for (int krow = 0; krow < kernel_dim; krow++) {
122:                         for (int kcol = 0; kcol < kernel_dim; kcol++) {
123:                             for (int kch = 0; kch < in_channels; kch++) {
124:                                 int irow = orow * stride + krow - padding;
125:                                 int icol = ocol * stride + kcol - padding;
126: 
127:                                 elem_t pixel = irow < 0 || irow >= in_row_dim_dilated ||
128:                                     icol < 0 || icol >= in_col_dim_dilated ?
129:                                     0 : dilated[b][irow][icol][kch];
130: 
131:                                 elem_t w = wrot180 ?
132:                                     weights_rot180[och][krow][kcol][kch] :
133:                                     weights[och][krow][kcol][kch];
134: 
135:                                 result += w * pixel;
136:                             }
137:                         }
138:                     }
139: 
140:                     // Clip result
141:                     result = result > elem_t_max ? elem_t_max : (result < elem_t_min ? elem_t_min : result);
142: 
143:                     output[b][orow][ocol][och] = result;
144:                 }
145:             }
146:         }
147:     }
148: }
