 68: void conv(int batch_size, int in_channels,
 69:         int in_row_dim, int in_col_dim,
 70:         int out_channels, int kernel_dim,
 71:         int out_row_dim, int out_col_dim,
 72:         int stride, int input_dilation, int padding,
 73:         elem_t input[batch_size][in_row_dim][in_col_dim][in_channels],
 74:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
 75:         acc_t bias[out_channels],
 76:         elem_t output[batch_size][out_row_dim][out_col_dim][out_channels]) {
 77: 
 78:     const size_t in_row_dim_dilated = in_row_dim + (input_dilation - 1) * (in_row_dim - 1);
 79:     const size_t in_col_dim_dilated = in_col_dim + (input_dilation - 1) * (in_col_dim - 1);
 80:     assert(in_row_dim_dilated == IN_ROW_DIM_DILATED);
 81:     assert(in_col_dim_dilated == IN_COL_DIM_DILATED);
 82:     static elem_t dilated[BATCH_SIZE][IN_ROW_DIM_DILATED][IN_COL_DIM_DILATED][IN_CHANNELS];
 83: 
 84: #ifdef GEMMINI_ASSERTIONS
 85:     if (out_row_dim != (in_row_dim_dilated + 2 * padding - kernel_dim) / stride + 1) {
 86:         printf("conv out_row_dim is not correct\n");
 87:         printf("out_row_dim\n");
 88:         exit(1);
 89:     }
 90:     if (out_col_dim != (in_col_dim_dilated + 2 * padding - kernel_dim) / stride + 1) {
 91:         printf("conv out_col_dim is not correct\n");
 92:         printf("out_col_dim\n");
 93:         exit(1);
 94:     }
 95: #endif
 96: 
 97:     for (int b = 0; b < batch_size; b++)
 98:         for (int irow = 0; irow < in_row_dim_dilated; irow++)
 99:             for (int icol = 0; icol < in_col_dim_dilated; icol++)
100:                 for (int ich = 0; ich < in_channels; ich++)
101:                     dilated[b][irow][icol][ich] = 0;
102: 
103:     size_t idx = 0;
104:     for (int b = 0; b < batch_size; b++)
105:         for (int irow = 0; irow < in_row_dim_dilated; irow += input_dilation)
106:             for (int icol = 0; icol < in_col_dim_dilated; icol += input_dilation)
107:                 for (int ich = 0; ich < in_channels; ich++) {
108:                     dilated[b][irow][icol][ich] = *((elem_t*)input + idx);
109:                     idx++;
110:                 }
111: 
112:     for (int b = 0; b < batch_size; b++) {
113:         for (int orow = 0; orow < out_row_dim; orow++) {
114:             for (int ocol = 0; ocol < out_col_dim; ocol++) {
115:                 for (int och = 0; och < out_channels; och++) {
116:                     acc_t result = bias[och];
117: 
118:                     for (int krow = 0; krow < kernel_dim; krow++) {
119:                         for (int kcol = 0; kcol < kernel_dim; kcol++) {
120:                             for (int kch = 0; kch < in_channels; kch++) {
121:                                 int irow = orow * stride + krow - padding;
122:                                 int icol = ocol * stride + kcol - padding;
123: 
124:                                 elem_t pixel = irow < 0 || irow >= in_row_dim_dilated ||
125:                                     icol < 0 || icol >= in_col_dim_dilated ?
126:                                     0 : dilated[b][irow][icol][kch];
127: 
128:                                 result +=
129:                                     weights[och][krow][kcol][kch] *
130:                                     pixel;
131:                             }
132:                         }
133:                     }
134: 
135:                     // Clip result
136:                     result = result > elem_t_max ? elem_t_max : (result < elem_t_min ? elem_t_min : result);
137: 
138:                     output[b][orow][ocol][och] = result;
139:                 }
140:             }
141:         }
142:     }
143: }
