145: void flatten_weights(int out_channels, int kernel_dim, int in_channels,
146:         int patch_size,
147:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
148:         elem_t weights_mat[patch_size][out_channels]) {
149: 
150:     assert(patch_size == kernel_dim * kernel_dim * in_channels);
151: 
152:     for (int outc = 0; outc < out_channels; outc++) {
153:         for (int krow = 0; krow < kernel_dim; krow++) {
154:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
155:                 for (int inc = 0; inc < in_channels; inc++) {
156:                     int wmatrow = krow * kernel_dim * in_channels +
157:                         kcol * in_channels +
158:                         inc;
159: 
160:                     weights_mat[wmatrow][outc] =
161:                         weights[outc][krow][kcol][inc];
162:                 }
163:             }
164:         }
165:     }
166: }
