175: void init_random(elem_t * buf, int len) {
176:     elem_t i = 0;
177:     for (elem_t * ptr = buf; ptr < buf + len; ptr++) {
178:         // *ptr = (rand() % 32) - 16;
179: #ifdef FAST
180:       *ptr = 1;
181: #else
182:       *ptr = (rand() % 5) - 2;
183: #endif
184:     }
185: }
