187: void init_random_acc(acc_t * buf, int len) {
188:     elem_t i = 0;
189:     for (acc_t * ptr = buf; ptr < buf + len; ptr++) {
190:         // *ptr = (rand() % 32) - 16;
191: #ifdef FAST
192:       *ptr = 1;
193: #else
194:       *ptr = (rand() % 5) - 2;
195: #endif
196:     }
197: }
198: 
199: void init_zeros_acc(acc_t * buf, int len) {
200:     for (acc_t * ptr = buf; ptr < buf + len; ptr++) {
201:         *ptr = 0;
202:     }
203: }
