 61: void conv(int batch_size, int in_channels,
 62:         int in_row_dim, int in_col_dim,
 63:         int out_channels, int kernel_dim,
 64:         int out_row_dim, int out_col_dim,
 65:         int stride, int input_dilation, int kernel_dilation, int padding,
 66:         elem_t input[batch_size][in_row_dim][in_col_dim][in_channels],
 67:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
 68:         acc_t bias[out_channels],
 69:         elem_t output[batch_size][out_row_dim][out_col_dim][out_channels]) {
 70: 
 71:     const size_t in_row_dim_dilated = in_row_dim + (input_dilation - 1) * (in_row_dim - 1);
 72:     const size_t in_col_dim_dilated = in_col_dim + (input_dilation - 1) * (in_col_dim - 1);
 73:     assert(in_row_dim_dilated == IN_ROW_DIM_DILATED);
 74:     assert(in_col_dim_dilated == IN_COL_DIM_DILATED);
 75:     static elem_t dilated[BATCH_SIZE][IN_ROW_DIM_DILATED][IN_COL_DIM_DILATED][IN_CHANNELS];
 76: 
 77:     const size_t kernel_dim_dilated = kernel_dim + (kernel_dilation - 1)*(kernel_dim - 1);
 78:     assert(kernel_dim_dilated == KERNEL_DIM_DILATED);
 79:     static elem_t weights_dilated[OUT_CHANNELS][KERNEL_DIM_DILATED][KERNEL_DIM_DILATED][IN_CHANNELS];
 80: 
 81: #ifdef GEMMINI_ASSERTIONS
 82:     if (out_row_dim != (in_row_dim_dilated + 2 * padding - kernel_dim_dilated) / stride + 1) {
 83:         printf("conv out_row_dim is not correct\n");
 84:         printf("out_row_dim\n");
 85:         exit(1);
 86:     }
 87:     if (out_col_dim != (in_col_dim_dilated + 2 * padding - kernel_dim_dilated) / stride + 1) {
 88:         printf("conv out_col_dim is not correct\n");
 89:         printf("out_col_dim\n");
 90:         exit(1);
 91:     }
 92: #endif
 93: 
 94:     for (int b = 0; b < batch_size; b++)
 95:         for (int irow = 0; irow < in_row_dim_dilated; irow++)
 96:             for (int icol = 0; icol < in_col_dim_dilated; icol++)
 97:                 for (int ich = 0; ich < in_channels; ich++)
 98:                     dilated[b][irow][icol][ich] = 0;
 99: 
100:     size_t idx = 0;
101:     for (int b = 0; b < batch_size; b++)
102:         for (int irow = 0; irow < in_row_dim_dilated; irow += input_dilation)
103:             for (int icol = 0; icol < in_col_dim_dilated; icol += input_dilation)
104:                 for (int ich = 0; ich < in_channels; ich++) {
105:                     dilated[b][irow][icol][ich] = *((elem_t*)input + idx);
106:                     idx++;
107:                 }
108: 
109:     for (int och = 0; och < out_channels; och++)
110:         for (int krow = 0; krow < kernel_dim_dilated; krow++)
111:             for (int kcol = 0; kcol < kernel_dim_dilated; kcol++)
112:                 for (int kch = 0; kch < in_channels; kch++)
113:                     weights_dilated[och][krow][kcol][kch] = 0;
114: 
115:     idx = 0;
116:     for (int och = 0; och < out_channels; och++)
117:         for (int krow = 0; krow < kernel_dim_dilated; krow += kernel_dilation)
118:             for (int kcol = 0; kcol < kernel_dim_dilated; kcol += kernel_dilation)
119:                 for (int kch = 0; kch < in_channels; kch++) {
120:                     weights_dilated[och][krow][kcol][kch] = *((elem_t*)weights + idx);
121:                     idx++;
122:                 }
123: 
124:     for (int b = 0; b < batch_size; b++) {
125:         for (int orow = 0; orow < out_row_dim; orow++) {
126:             for (int ocol = 0; ocol < out_col_dim; ocol++) {
127:                 for (int och = 0; och < out_channels; och++) {
128:                     acc_t result = bias[och];
129: 
130:                     for (int krow = 0; krow < kernel_dim_dilated; krow++) {
131:                         for (int kcol = 0; kcol < kernel_dim_dilated; kcol++) {
132:                             for (int kch = 0; kch < in_channels; kch++) {
133:                                 int irow = orow * stride + krow - padding;
134:                                 int icol = ocol * stride + kcol - padding;
135: 
136:                                 elem_t pixel = irow < 0 || irow >= in_row_dim_dilated ||
137:                                     icol < 0 || icol >= in_col_dim_dilated ?
138:                                     0 : dilated[b][irow][icol][kch];
139: 
140:                                 result +=
141:                                     weights_dilated[och][krow][kcol][kch] *
142:                                     pixel;
143:                             }
144:                         }
145:                     }
146: 
147:                     // Clip result
148:                     result = result > elem_t_max ? elem_t_max : (result < elem_t_min ? elem_t_min : result);
149: 
150:                     output[b][orow][ocol][och] = result;
151:                 }
152:             }
153:         }
154:     }
155: }
