157: void flatten_weights(int out_channels, int kernel_dim, int in_channels,
158:         int patch_size,
159:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
160:         elem_t weights_mat[patch_size][out_channels]) {
161: 
162:     assert(patch_size == kernel_dim * kernel_dim * in_channels);
163: 
164:     for (int outc = 0; outc < out_channels; outc++) {
165:         for (int krow = 0; krow < kernel_dim; krow++) {
166:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
167:                 for (int inc = 0; inc < in_channels; inc++) {
168:                     int wmatrow = krow * kernel_dim * in_channels +
169:                         kcol * in_channels +
170:                         inc;
171: 
172:                     weights_mat[wmatrow][outc] =
173:                         weights[outc][krow][kcol][inc];
174:                 }
175:             }
176:         }
177:     }
178: }
