150: void flatten_weights(int out_channels, int kernel_dim, int in_channels,
151:         int patch_size,
152:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
153:         elem_t weights_mat[patch_size][out_channels]) {
154: 
155:     assert(patch_size == kernel_dim * kernel_dim * in_channels);
156: 
157:     for (int outc = 0; outc < out_channels; outc++) {
158:         for (int krow = 0; krow < kernel_dim; krow++) {
159:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
160:                 for (int inc = 0; inc < in_channels; inc++) {
161:                     int wmatrow = krow * kernel_dim * in_channels +
162:                         kcol * in_channels +
163:                         inc;
164: 
165:                     weights_mat[wmatrow][outc] =
166:                         weights[outc][krow][kcol][inc];
167:                 }
168:             }
169:         }
170:     }
171: }
