192: void init_random_acc(acc_t * buf, int len) {
193:     elem_t i = 0;
194:     for (acc_t * ptr = buf; ptr < buf + len; ptr++) {
195:         // *ptr = (rand() % 32) - 16;
196: #ifdef FAST
197:       *ptr = 1;
198: #else
199:       *ptr = (rand() % 5) - 2;
200: #endif
201:     }
202: }
