 54: void conv(int batch_size, int in_channels,
 55:         int in_row_dim, int in_col_dim,
 56:         int out_channels, int kernel_dim,
 57:         int out_row_dim, int out_col_dim,
 58:         int stride, int padding,
 59:         elem_t input[batch_size][in_row_dim][in_col_dim][in_channels],
 60:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
 61:         acc_t bias[out_channels],
 62:         elem_t output[batch_size][out_row_dim][out_col_dim][out_channels]) {
 63: 
 64: #ifdef GEMMINI_ASSERTIONS
 65:     if (out_row_dim != (in_row_dim + 2 * padding - kernel_dim) / stride + 1) {
 66:         printf("conv out_row_dim is not correct\n");
 67:         exit(1);
 68:     }
 69: 
 70:     if (out_col_dim != (in_col_dim + 2 * padding - kernel_dim) / stride + 1) {
 71:         printf("conv out_col_dim is not correct\n");
 72:         exit(1);
 73:     }
 74: #endif
 75: 
 76:     for (int b = 0; b < batch_size; b++) {
 77:         for (int orow = 0; orow < out_row_dim; orow++) {
 78:             for (int ocol = 0; ocol < out_col_dim; ocol++) {
 79:                 for (int och = 0; och < out_channels; och++) {
 80:                     acc_t result = bias[och];
 81: 
 82:                     for (int krow = 0; krow < kernel_dim; krow++) {
 83:                         for (int kcol = 0; kcol < kernel_dim; kcol++) {
 84:                             for (int kch = 0; kch < in_channels; kch++) {
 85:                                 int irow = orow * stride + krow - padding;
 86:                                 int icol = ocol * stride + kcol - padding;
 87: 
 88:                                 elem_t pixel = irow < 0 || irow >= in_row_dim ||
 89:                                     icol < 0 || icol >= in_col_dim ?
 90:                                     0 : input[b][irow][icol][kch];
 91: 
 92:                                 result +=
 93:                                     weights[och][krow][kcol][kch] *
 94:                                     pixel;
 95:                             }
 96:                         }
 97:                     }
 98: 
 99:                     // Clip result
100:                     result = result > elem_t_max ? elem_t_max : (result < elem_t_min ? elem_t_min : result);
101: 
102:                     output[b][orow][ocol][och] = result;
103:                 }
104:             }
105:         }
106:     }
107: }
108: 
109: void flatten_weights(int out_channels, int kernel_dim, int in_channels,
110:         int patch_size,
111:         elem_t weights[out_channels][kernel_dim][kernel_dim][in_channels],
112:         elem_t weights_mat[patch_size][out_channels]) {
113: 
114:     assert(patch_size == kernel_dim * kernel_dim * in_channels);
115: 
116:     for (int outc = 0; outc < out_channels; outc++) {
117:         for (int krow = 0; krow < kernel_dim; krow++) {
118:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
119:                 for (int inc = 0; inc < in_channels; inc++) {
120:                     int wmatrow = krow * kernel_dim * in_channels +
121:                         kcol * in_channels +
122:                         inc;
123: 
124:                     weights_mat[wmatrow][outc] =
125:                         weights[outc][krow][kcol][inc];
126:                 }
127:             }
128:         }
129:     }
130: }
