151: void init_random_acc(acc_t * buf, int len) {
152:     elem_t i = 0;
153:     for (acc_t * ptr = buf; ptr < buf + len; ptr++) {
154:         // *ptr = (rand() % 32) - 16;
155: #ifdef FAST
156:       *ptr = 1;
157: #else
158:       *ptr = (rand() % 5) - 2;
159: #endif
160:     }
161: }
