 19: int main() {
 20: #ifndef BAREMETAL
 21:     if (mlockall(MCL_CURRENT | MCL_FUTURE) != 0) {
 22:       perror("mlockall failed");
 23:       exit(1);
 24:     }
 25: #endif
 26: 
 27:   gemmini_flush(0);
 28: 
 29:   // Set counter and reset
 30:   counter_configure(0, LOAD_ACTIVE_CYCLE);
 31:   if(counter_read(0) != 0) {
 32:     printf("Counter Reset Failed (not equal to 0)\n");
 33:     exit(1);
 34:   }
 35: 
 36:   // Initial matrix
 37:   gemmini_config_ld(DIM * sizeof(elem_t));
 38:   gemmini_config_st(DIM * sizeof(elem_t));
 39: 
 40:   static elem_t In[N][DIM][DIM] row_align(1);
 41:   static elem_t Out[N][DIM][DIM] row_align(1);
 42: 
 43:   for (size_t n = 0; n < N; ++n)
 44:     for (size_t i = 0; i < DIM; ++i)
 45:       for (size_t j = 0; j < DIM; ++j)
 46:         In[n][i][j] = i*DIM + j + n;
 47: 
 48:   // Move in
 49:   for (size_t i = 0; i < N; i++) {
 50:     gemmini_mvin(In[i], i*DIM);
 51:     gemmini_mvout(Out[i], i*DIM);
 52:   }
 53: 
 54:   // Check value (should be increasing right now as Gemmini executes in the background)
 55:   int counter_val = counter_read(0);
 56: 
 57:   // Take a snapshot
 58:   counter_snapshot_take();
 59:   int snapshot_val = counter_read(0);
 60: 
 61:   // Print first counter value (Syscall takes a lot of time, and we might not capture a snapshot when
 62:   // the instructions are still being executed)
 63:   printf("Read DMA cycles: %d\n", counter_val);
 64:   if (counter_val == 0) {
 65:     printf("Counter Value failed to increase\n");
 66:     exit(1);
 67:   } 
 68: 
 69:   // Wait till the operation finish
 70:   gemmini_fence();
 71: 
 72:   // Check again
 73:   counter_val = counter_read(0);
 74:   printf("Cycle when taking snapshot: %d, Cycle read after operation finished: %d\n",
 75:     snapshot_val, counter_val);
 76:   if (counter_val != snapshot_val) {
 77:     printf("Snapshot changed after taken; test failed\n");
 78:     exit(1);
 79:   }
 80: 
 81:   // Reset snapshot, and check if cycles changed
 82:   counter_snapshot_reset();
 83:   counter_val = counter_read(0);
 84:   printf("Cycles after snapshot is reset: %d\n", counter_val);
 85:   if (counter_val < snapshot_val + 10) {
 86:     printf("Counter values changed too little after snapshot reset; check if counter continues properly\n");
 87:     exit(1);
 88:   }
 89: 
 90:   // Global reset
 91:   counter_reset();
 92:   counter_val = counter_read(0);
 93:   printf("Cycles after counter reset: %d\n", counter_val);
 94:   if (counter_val != 0) {
 95:     printf("Cycles did not reset after global reset inst\n");
 96:     exit(1);
 97:   }
 98: 
 99:   // Check external counter
100:   counter_configure(7, RESERVATION_STATION_LD_COUNT);
101:   for (size_t i = 0; i < N; i++) {
102:     gemmini_mvin(In[i], i*DIM);
103:     gemmini_mvout(Out[i], i*DIM);
104:   }
105: 
106:   // Fused read and take snapshot command
107:   uint32_t custom_command = (7 & 0x7) << 4 | 0x4;
108:   gemmini_counter_access(counter_val, custom_command);
109: 
110:   printf("RESERVATION_STATION # of load insts after executing %d mvin and mvout insts: %d\n", N-1, counter_val);
111:   if (counter_val < 2) {
112:     printf("The load RESERVATION_STATION counter value is too small\n");
113:     exit(1);
114:   }
115: 
116:   snapshot_val = counter_read(7);
117:   if (counter_val != snapshot_val) {
118:     printf("Snapshot value doesn't match the raw value read before snapshot taken\n");
119:     exit(1);
120:   }
121: 
122:   exit(0);
