 48:   for (int activation = AINIT; activation <= RELU; ++activation) {
 49:     for (int shift = SINIT; shift <= 12; shift += 4) {
 50:       // printf("activation: %d, shift: %d\n", activation, shift);
 51: 
 52:       static elem_t A[N][DIM][DIM] row_align(1);
 53:       static elem_t B[N][DIM][DIM] row_align(1);
 54:       static elem_t D[N][DIM][DIM] row_align(1);
 55: 
 56:       // We will try out every combination of A, B, D possible
 57:       static elem_t C[N*N*N][DIM][DIM] row_align(1);
 58:       static full_t gold_full[N*N*N][DIM][DIM];
 59:       static elem_t gold[N*N*N][DIM][DIM];
 60: 
 61:       // ...taking into account the preloads or accumulates
 62:       static int preload[N*N*N] = {1};
 63:       for (int i = 1; i < N*N*N; ++i)
 64:         preload[i] = rand() % 2;
 65: 
 66:       // ...and for the actual preloads, do we just preload zeros?
 67:       static int preload_zeros[N*N*N];
 68:       for (int i = 0; i < N*N*N; ++i)
 69:         preload_zeros[i] = rand() % 2;
 70: 
 71:       // ...and finally, which results won't produce any output
 72:       static int no_output[N*N*N];
 73:       for (int i = 0; i < N*N*N-1; ++i)
 74:         no_output[i] = !preload[i+1];
 75:       no_output[N*N*N-1] = 0;
