 83:       for (int i = 0; i < N*N*N; ++i)
 84:         printf("%d, ", preload_zeros[i]);
 85:       printf("\n");
 86:       printf("No outputs: ");
 87:       for (int i = 0; i < N*N*N; ++i)
 88:         printf("%d, ", no_output[i]);
 89:       printf("\n");*/
 90: 
 91:       for (size_t n = 0; n < N; ++n) {
 92:         for (size_t i = 0; i < DIM; ++i) {
 93:           for (size_t j = 0; j < DIM; ++j) {
 94:             A[n][i][j] = (rand() % 64) - 32;
 95:             B[n][i][j] = (rand() % 64) - 32;
 96:             D[n][i][j] = (rand() % 64) - 32;
 97:           }
 98:         }
 99:       }
100: 
101:       for (size_t g = 0; g < N*N*N; ++g) {
102:         int a, b, d; 
103:         operands(g, &a, &b, &d);
104: 
105:         if (!preload[g])
106:           matmul_full(A[a], B[b], gold_full[g-1], gold_full[g]);
107:         else if (preload_zeros[g])
108:           matmul(A[a], B[b], ZERO, gold_full[g]);
109:         else
110:           matmul(A[a], B[b], D[d], gold_full[g]);
111:       }
112: 
113:       for (size_t g = 0; g < N*N*N; ++g) {
114:           matshift(gold_full[g], gold[g], shift);
115:           if (activation == RELU)
116:             matrelu(gold[g], gold[g]);
117:       }
118: 
119:       int A_addr = 0;
120:       int B_addr = N*DIM;
121:       int D_addr = 2*N*DIM;
122:       int C_addr = 3*N*DIM;
123: 
124:       // printf("Moving in\n");
125:       for (size_t n = 0; n < N; ++n)
126:         gemmini_mvin(A[n], A_addr + n*DIM);
127:       
128:       for (size_t n = 0; n < N; ++n)
129:         gemmini_mvin(B[n], B_addr + n*DIM);
130: 
131:       for (size_t n = 0; n < N; ++n) {
132:         gemmini_mvin(D[n], D_addr + n*DIM);
133:       }
134: 
135:       // printf("Setting mode\n");
136:       gemmini_config_ex(OUTPUT_STATIONARY, activation, shift);
137: 
138:       // printf("Matmulling\n");
