 40: void test_os (bool A_transpose, bool B_transpose) {
 41:   // Output stationary
 42:   printf("Output-stationary\n");
 43: 
 44:   void (*matmul_ptr)(elem_t[DIM][DIM], elem_t[DIM][DIM], elem_t[DIM][DIM], full_t[DIM][DIM]);
 45:   void (*matmul_full_ptr)(elem_t[DIM][DIM], elem_t[DIM][DIM], full_t[DIM][DIM], full_t[DIM][DIM]);
 46: 
 47:   if (!A_transpose && !B_transpose) {
 48:     matmul_ptr = &matmul;
 49:     matmul_full_ptr = &matmul_full;
 50:   } else if (A_transpose && !B_transpose) {
 51:     matmul_ptr = &matmul_A_transposed;
 52:     matmul_full_ptr = &matmul_full_A_transposed;
 53:   } else if (!A_transpose && B_transpose) {
 54:     // Just return immediately because we don't support this
 55:     return;
 56:   } else if (A_transpose && B_transpose) {
 57:     matmul_ptr = &matmul_AB_transposed;
 58:     matmul_full_ptr = &matmul_full_AB_transposed;
 59:   }
 60: 
 61:   for (int activation = AINIT; activation <= RELU; ++activation) {
 62:     for (int shift = SINIT; shift <= 4; shift += 4) {
 63:       // printf("activation: %d, shift: %d\n", activation, shift);
 64: 
 65:       static elem_t A[N][DIM][DIM] row_align(1);
 66:       static elem_t B[N][DIM][DIM] row_align(1);
 67:       static elem_t D[N][DIM][DIM] row_align(1);
 68: 
 69:       // We will try out every combination of A, B, D possible
 70:       static elem_t C[N*N*N][DIM][DIM] row_align(1);
 71:       static full_t gold_full[N*N*N][DIM][DIM];
 72:       static elem_t gold[N*N*N][DIM][DIM];
 73: 
 74:       // ...taking into account the preloads or accumulates
 75:       static int preload[N*N*N] = {1};
 76:       for (int i = 1; i < N*N*N; ++i)
 77:         preload[i] = 1; // rand() % 2;
 78: 
 79:       // ...and for the actual preloads, do we just preload zeros?
 80:       static int preload_zeros[N*N*N];
 81:       for (int i = 0; i < N*N*N; ++i)
 82:         preload_zeros[i] = 1; // rand() % 2;
 83: 
 84:       // ...and finally, which results won't produce any output
 85:       static int no_output[N*N*N];
 86:       for (int i = 0; i < N*N*N-1; ++i)
 87:         no_output[i] = !preload[i+1];
 88:       no_output[N*N*N-1] = 0;
 89: 
 90:       // Print the sequence out
 91:       /*printf("Preloads: ");
 92:       for (int i = 0; i < N*N*N; ++i)
 93:         printf("%d, ", preload[i]);
 94:       printf("\n");
 95:       printf("Zeros: ");
 96:       for (int i = 0; i < N*N*N; ++i)
 97:         printf("%d, ", preload_zeros[i]);
 98:       printf("\n");
 99:       printf("No outputs: ");
100:       for (int i = 0; i < N*N*N; ++i)
101:         printf("%d, ", no_output[i]);
102:       printf("\n");*/
103: 
104:       for (size_t n = 0; n < N; ++n) {
105:         for (size_t i = 0; i < DIM; ++i) {
106:           for (size_t j = 0; j < DIM; ++j) {
107:             A[n][i][j] = (RAND % 64) - 32;
108:             B[n][i][j] = (RAND % 64) - 32;
109:             D[n][i][j] = (RAND % 64) - 32;
110:           }
111:         }
112:       }
113:  #ifdef FAST1
114:         for (size_t i = 0; i < DIM; ++i) {
115:           for (size_t j = 0; j < DIM; ++j) {
116:             gold[0][i][j] = 1;
117:           }
118:         }
119: #else
120:       for (size_t g = 0; g < N*N*N; ++g) {
121:         int a, b, d; 
122:         operands(g, &a, &b, &d);
123: 
124:         if (!preload[g])
125:           (*matmul_full_ptr)(A[a], B[b], gold_full[g-1], gold_full[g]);
126:         else if (preload_zeros[g]) {
127:           (*matmul_ptr)(A[a], B[b], ZERO, gold_full[g]);
128:         } else {
129:           (*matmul_ptr)(A[a], B[b], D[d], gold_full[g]);
130:         }
131:       }
132: 
133:       for (size_t g = 0; g < N*N*N; ++g) {
134:         matshift(gold_full[g], gold[g], shift);
135:         if (activation == RELU)
136:           matrelu(gold[g], gold[g]);
137:       }
138: #endif
139:       int A_addr = 0;
140:       int B_addr = N*DIM;
141:       int D_addr = 2*N*DIM;
142:       int C_addr = 3*N*DIM;
143: 
144:       // printf("Moving in\n");
145:       for (size_t n = 0; n < N; ++n)
146:         gemmini_mvin(A[n], A_addr + n*DIM);
147:       
148:       for (size_t n = 0; n < N; ++n)
149:         gemmini_mvin(B[n], B_addr + n*DIM);
150: 
151:       for (size_t n = 0; n < N; ++n) {
152:         gemmini_mvin(D[n], D_addr + n*DIM);
153:       }
154: 
155:       // printf("Setting mode\n");
156:       gemmini_extended_config_ex(OUTPUT_STATIONARY, activation, shift, 1, A_transpose, B_transpose);
157: 
158:       // printf("Matmulling\n");
159:       for (size_t c = 0; c < N*N*N; ++c) {
160:         int a, b, d;
161:         operands(c, &a, &b, &d);
162:         
163:         uint64_t out_addr = C_addr + c*DIM;
164:         if (no_output[c])
165:           out_addr = GARBAGE_ADDR;
166: 
167:         if (!preload[c]) {
168:           gemmini_preload_zeros(out_addr);
169:           gemmini_compute_accumulated(A_addr + a*DIM, B_addr + b*DIM);
170:         } else if (preload_zeros[c]) {
171:           gemmini_preload_zeros(out_addr);
172:           gemmini_compute_preloaded(A_addr + a*DIM, B_addr + b*DIM);
173:         } else {
174:           gemmini_preload(D_addr + d*DIM, out_addr);
175:           gemmini_compute_preloaded(A_addr + a*DIM, B_addr + b*DIM);
176:         }
177:       }
178: 
179:       // printf("Moving out\n");
180:       for (size_t c = 0; c < N*N*N; ++c)
181:         if (!no_output[c]) {
182:           gemmini_mvout_spad(C_addr + c*DIM + N*N*N * DIM, C_addr + c*DIM); // mvout to spad, then to dram
183:           gemmini_mvout(C[c], C_addr + c*DIM + N*N*N * DIM);
184:         }
185: 
186:       gemmini_fence();
187:       printf("moved out\n");
188: 
189:       /*
190:       printf("Moved out\n");
191: 
192:       printf("A[0]:\n");
193:       printMatrix(A[0]);
194:       printf("B[0]:\n");
195:       printMatrix(B[0]);
196: 
197:       for (int n = 0; n < N*N*N; ++n) {
198:         if (!no_output[n]) {
199:           printf("C:\n");
200:           printMatrix(C[n]);
201:           printf("Gold:\n");
202:           printMatrix(gold[n]);
203:           printf("\n");
204:         }
205:       }
206:       */
207: 
208:       for (int n = 0; n < N*N*N; ++n)
209:         if (!no_output[n] && !is_equal(C[n], gold[n])) {
210:           printf("activation: %d, shift: %d, n: %d, A_transpose: %d, B_transpose: %d\n", activation, shift, n, A_transpose, B_transpose);
211: 
212:           printf("A:\n");
213:           printMatrix(A[n]);
214:           printf("B:\n");
215:           printMatrix(B[n]);
216:           printf("C:\n");
217:           printMatrix(C[n]);
218:           printf("Gold:\n");
219:           printMatrix(gold[n]);
220:           printf("\n");
221: 
222:           exit(1);
223:         }
224:     }
225:   }
226: }
