228: void test_ws(bool A_transpose, bool B_transpose) {
229:   // Weight-stationary
230:   printf("Weight-stationary\n");
231: 
232:   void (*matmul_ptr)(elem_t[DIM][DIM], elem_t[DIM][DIM], elem_t[DIM][DIM], full_t[DIM][DIM]);
233: 
234:   if (!A_transpose && !B_transpose) {
235:     matmul_ptr = &matmul;
236:   } else if (A_transpose && !B_transpose) {
237:     matmul_ptr = &matmul_A_transposed;
238:   } else if (!A_transpose && B_transpose) {
239:     matmul_ptr = &matmul_B_transposed;
240:   } else if (A_transpose && B_transpose) {
241:     return;
242:   }
243: 
244:   for (int activation = AINIT; activation <= RELU; ++activation) {
245:     for (int scale = SINIT; scale <= 4; scale += 4) {
246:       static elem_t A[N][DIM][DIM] row_align(1);
247:       static elem_t B[N][DIM][DIM] row_align(1);
248:       static elem_t D[N][DIM][DIM] row_align(1);
249: 
250:       // We will try out every combination of A, B, D possible
251:       static elem_t C[N*N*N][DIM][DIM] row_align(1);
252:       static full_t gold_full[N*N*N][DIM][DIM];
253:       static elem_t gold[N*N*N][DIM][DIM];
254: 
255:       // ...taking into account whether we preload new weights or re-use the old ones
256:       static int preload[N*N*N] = {1};
257:       for (int i = 1; i < N*N*N; ++i)
258:         preload[i] = RAND % 2;
259: 
260:       // ...whether we pass in a D or just use zeros
261:       static int add_to_zeros[N*N*N];
262:       for (int i = 0; i < N*N*N; ++i)
263:         add_to_zeros[i] = RAND % 2;
264: 
265:       // ...and whether we accumulate on top of the previous result
266:       static int accumulate[N*N*N] = {0};
267:       for (int i = 1; i < N*N*N; ++i)
268:         accumulate[i] = RAND % 2;
269: 
270:       static int no_output[N*N*N];
271:       for (int i = 0; i < N*N*N-1; ++i)
272:         no_output[i] = accumulate[i+1];
273:       no_output[N*N*N-1] = 0;
274: 
275:       // Print the sequence out
276:       /*printf("Preloads: ");
277:       for (int i = 0; i < N*N*N; ++i)
278:         printf("%d, ", preload[i]);
279:       printf("\n");
280:       printf("Zeros: ");
281:       for (int i = 0; i < N*N*N; ++i)
282:         printf("%d, ", add_to_zeros[i]);
283:       printf("\n");
284:       printf("Accumulates: ");
285:       for (int i = 0; i < N*N*N; ++i)
286:         printf("%d, ", accumulate[i]);
287:       printf("\n");
288:       printf("No outputs: ");
289:       for (int i = 0; i < N*N*N; ++i)
290:         printf("%d, ", no_output[i]);
291:       printf("\n");*/
292: 
293:       for (size_t n = 0; n < N; ++n) {
294:         for (size_t i = 0; i < DIM; ++i) {
295:           for (size_t j = 0; j < DIM; ++j) {
296:             A[n][i][j] = (RAND % 64) - 32;
297:             B[n][i][j] = (RAND % 64) - 32;
298:             D[n][i][j] = (RAND % 64) - 32;
299:           }
300:         }
301:       }
302: #ifdef FAST1
303:       for (size_t i = 0; i < DIM; ++i) {
304: 	for (size_t j = 0; j < DIM; ++j) {
305: 	  gold[0][i][j] = 64;
306:         }
307:       }
308: #else
309:       for (size_t g = 0; g < N*N*N; ++g) {
310:         int a, b, d;
311:         operands(g, &a, &b, &d);
312: 
313:         // We need to find the last B value in case we aren't preloading new weights
314:         for (int last_g = g; last_g >= 0; --last_g) {
315:             int tmp_a, tmp_d;
316:             if (preload[last_g]) {
317:                 operands(last_g, &tmp_a, &b, &tmp_d);
318:                 break;
319:             }
320:         }
321: 
322:         if (add_to_zeros[g]) {
323:           (*matmul_ptr)(A[a], B[b], ZERO, gold_full[g]);
324:         } else {
325:           (*matmul_ptr)(A[a], B[b], D[d], gold_full[g]);
326:         }
327: 
328:         if (accumulate[g])
329:           matadd(gold_full[g], gold_full[g-1], gold_full[g]);
330:       }
331: 
332:       for (size_t g = 0; g < N*N*N; ++g) {
333:         matscale(gold_full[g], gold[g], scale);
334:         if (activation == RELU)
335:           matrelu(gold[g], gold[g]);
336:       }
337: #endif
338:       uint32_t A_addr = 0;
339:       uint32_t B_addr = N*DIM;
340:       uint32_t D_addr = 2*N*DIM;
341:       uint32_t C_addr_acc = 1 << (ADDR_LEN-1);
342: 
343:       // Calculate the proper destination addresses of everything
344:       uint32_t C_addrs[N*N*N];
345:       for (size_t c = 0; c < N*N*N; ++c)
346:         C_addrs[c] = C_addr_acc + c*DIM;
347:       for (size_t c = 0; c < N*N*N; ++c) {
348:         int last_c;
349:         for (last_c = c; last_c >= 0; --last_c)
350:           if (!accumulate[last_c])
351:             break;
352:         if (c != last_c)
353:           C_addrs[c] = C_addrs[last_c] | (1 << (ADDR_LEN-2));
354:       }
355: 
356:       // printf("Moving in\n");
357:       for (size_t n = 0; n < N; ++n)
358:         gemmini_mvin(A[n], A_addr + n*DIM);
359: 
360:       for (size_t n = 0; n < N; ++n)
361:         gemmini_mvin(B[n], B_addr + n*DIM);
362: 
363:       for (size_t n = 0; n < N; ++n)
364:         gemmini_mvin(D[n], D_addr + n*DIM);
365: 
366:       // printf("Setting mode\n");
367:       gemmini_extended_config_ex(WEIGHT_STATIONARY, 0, 0, 1, A_transpose, B_transpose);
368:       gemmini_extended_config_st(DIM * sizeof(elem_t), activation, scale);
369: 
370:       // printf("Matmulling\n");
371:       for (size_t c = 0; c < N*N*N; ++c) {
372:         int a, b, d;
373:         operands(c, &a, &b, &d);
374: 
375:         uint64_t d_addr = D_addr + d*DIM;
376:         if (add_to_zeros[c])
377:           d_addr = GARBAGE_ADDR;
378: 
379:         if (!preload[c]) {
380:           gemmini_preload_zeros(C_addrs[c]);
381:           gemmini_compute_accumulated(A_addr + a*DIM, d_addr);
382:         } else {
383:           gemmini_preload(B_addr + b*DIM, C_addrs[c]);
384:           gemmini_compute_preloaded(A_addr + a*DIM, d_addr);
385:         }
386:       }
387: 
388:       // printf("Moving out\n");
389:       for (size_t c = 0; c < N*N*N; ++c)
390:         if (!no_output[c]) {
391:           uint32_t addr = C_addrs[c] & ~(1 << (ADDR_LEN-2));
392:           gemmini_mvout_spad(c * DIM, addr);
393:           gemmini_mvout(C[c], c * DIM);
394:         }
395: 
396:       gemmini_fence();
397: 
398:       /*printf("Moved out\n");
399:       for (int n = 0; n < N*N*N; ++n) {
400:         if (!no_output[n]) {
401:           printf("C:\n");
402:           printMatrix(C[n]);
403:           printf("Gold:\n");
404:           printMatrix(gold[n]);
405:           printf("\n");
406:         }
407:       }*/
408: 
409:       for (int n = 0; n < N*N*N; ++n)
410:         if (!no_output[n] && !is_equal(C[n], gold[n])) {
411:           printf("activation: %d, scale: %d, n: %d, A_transpose: %d, B_transpose: %d\n", activation, scale, n, A_transpose, B_transpose);
412: 
413:           printf("A:\n");
414:           printMatrix(A[n]);
415:           printf("B:\n");
416:           printMatrix(B[n]);
417:           printf("C:\n");
418:           printMatrix(C[n]);
419:           printf("Gold:\n");
420:           printMatrix(gold[n]);
421:           printf("\n");
422: 
423:           exit(1);
424:         }
425:     }
426:   }
427: }
