429: int main() {
430: #ifndef BAREMETAL
431:     if (mlockall(MCL_CURRENT | MCL_FUTURE) != 0) {
432:       perror("mlockall failed");
433:       exit(1);
434:     }
435: #endif
436: 
437:   gemmini_flush(0);
438:   gemmini_config_ld(DIM * sizeof(elem_t));
439:   gemmini_config_st(DIM * sizeof(elem_t));
440: 
441:   for (int A_transpose = 0; A_transpose < 2; A_transpose++) {
442:     for (int B_transpose = 0; B_transpose < 2; B_transpose++) {
443:       for (int dataflow = OUTPUT_STATIONARY; dataflow <= WEIGHT_STATIONARY; dataflow++) {
444:         printf("A_transpose: %d, B_transpose: %d, dataflow: %d\n", A_transpose, B_transpose, dataflow);
445: 
446:         if (dataflow == OUTPUT_STATIONARY)
447:           test_os(A_transpose, B_transpose);
448:         else
449:           test_ws(A_transpose, B_transpose);
450:       }
451:     }
452:   }
453: 
454:   exit(0);
