 34: int is_equal_big(acc_t x[BIG_DIM][BIG_DIM], acc_t y[BIG_DIM][BIG_DIM]) {
 35:   for (size_t i = 0; i < BIG_DIM; ++i)
 36:     for (size_t j = 0; j < BIG_DIM; ++j) {
 37: #ifndef ELEM_T_IS_FLOAT
 38:       if (x[i][j] != y[i][j]) {
 39: #else
 40:       bool isnanx = acc_t_isnan(x[i][j]);
 41:       bool isnany = acc_t_isnan(y[i][j]);
 42: 
 43:       if (x[i][j] != y[i][j] && !(isnanx && isnany)) {
 44:           printf("x[i][j] == %x\n", acc_t_to_acc_t_bits(x[i][j]));
 45:           printf("y[i][j] == %x\n", acc_t_to_acc_t_bits(y[i][j]));
 46: 
 47: #endif
 48:         printf("Unequal in row %u and column %u\n", i, j);
 49:         return 0;
 50:       }
 51:     }
 52:   return 1;
 53: }
