 55: void printMatrix_acc_big(acc_t m[BIG_DIM][BIG_DIM]) {
 56:   for (size_t i = 0; i < BIG_DIM; ++i) {
 57:     for (size_t j = 0; j < BIG_DIM; ++j)
 58: #ifndef ELEM_T_IS_FLOAT
 59:       printf("%d ", m[i][j]);
 60: #else
 61:       printf("%llx ", acc_t_to_acc_t_bits(m[i][j]));
 62: #endif
 63:     printf("\n");
 64:   }
 65: }
