 79:   for (int block_len = BINIT; block_len <= BIG_DIM/DIM && block_len <= MAX_BLOCK_LEN_ACC; block_len++) {
 80:     static acc_t In[BIG_DIM][BIG_DIM] row_align_acc(1);
 81:     static acc_t Out[BIG_DIM][BIG_DIM] row_align(1);
 82: 
 83:     for (size_t i = 0; i < BIG_DIM; ++i) {
 84:       for (size_t j = 0; j < BIG_DIM; ++j) {
 85: #ifndef ELEM_T_IS_FLOAT
 86:         In[i][j] = 0;
 87: #ifdef FAST
 88: #define RAND (j + i)
 89: #else
 90: #define RAND rand()
 91: #endif
 92:         int bytes = RAND % 2 ? sizeof(acc_t) : sizeof(elem_t);
 93:         for (size_t b = 0; b < bytes; ++b) {
 94:           In[i][j] |= (RAND % 255) << (b*8);
 95:         }
 96: #else
 97:         acc_t_bits data;
 98: 
 99:         do {
100:           data = 0;
101: 
102:           int bytes = rand() % 2 ? sizeof(acc_t) : sizeof(elem_t);
103:           for (size_t b = 0; b < bytes; ++b) {
104:             data |= (uint64_t)(rand() % 255) << (b*8);
105:           }
106: 
107:           In[i][j] = acc_t_bits_to_acc_t(data);
108:         } while (acc_t_isnan(In[i][j]));
109: #endif
110:       }
111:     }
112: 
113:     const uint32_t acc_addr = 5 << (ADDR_LEN-3);
114: 
115:     gemmini_config_ld(BIG_DIM*sizeof(acc_t));
