120:       for (size_t j = 0; j < BIG_DIM; j += DIM) {
121:         // printf("i: %u, j: %u\n", i, j);
122: 
123:         acc_t * dram_addr_in = &In[i][j];
124:         acc_t * dram_addr_out = &Out[i][j];
125:         uint32_t sp_addr = acc_addr + i*(BIG_DIM/DIM) + j;
126: 
127:         int already_moved_in = (j/DIM) % block_len != 0;
128: 
129:         if (!already_moved_in) {
130:           int len = j + block_len*DIM <= BIG_DIM ? block_len : (BIG_DIM-j)/DIM;
131:           // printf("Moving in with len: %d\n", len);
132:           gemmini_block_mvin(dram_addr_in, sp_addr, len);
133:           gemmini_mvout(dram_addr_out, sp_addr);
134:         } else {
135:           // printf("Already moved in\n");
136:           gemmini_mvout(dram_addr_out, sp_addr);
137:         }
138:       }
139:     }
140: 
141:     // printf("Fence\n");
142:     gemmini_fence();
143: 
144:     // printf("Check\n");
145:     if (!is_equal_big(Out, In)) {
146:       /*printf("Out:\n");
147:       for (size_t i = 0; i < BIG_DIM; i++) {
