156:       printf("Gold:\n");
157:       for (size_t i = 0; i < BIG_DIM; i++) {
158:         for (size_t j = 0; j < BIG_DIM; j++) {
159:           printf("%d, ", Out[i][j]);
160:         }
161:         printf("\n");
