 58: void matscale_big(full_t full[BIG_DIM][BIG_DIM], elem_t out[BIG_DIM][BIG_DIM], acc_scale_t scale) {
 59:   for (size_t r = 0; r < BIG_DIM; r++)
 60:     for (size_t c = 0; c < BIG_DIM; c++) {
 61:       // Scale element
 62:       full_t scaled = ACC_SCALE(full[r][c], scale);
 63: 
 64:       // Saturate and cast element
 65: #ifndef ELEM_T_IS_FLOAT
 66:       full_t elem = scaled > elem_t_max ? elem_t_max : (scaled < elem_t_min ? elem_t_min : scaled);
 67:       out[r][c] = elem;
 68: #else
 69:       out[r][c] = scaled; // TODO should we also saturate when using floats?
 70: #endif
 71:     }
 72: }
