 74: void matrelu_big(elem_t in[BIG_DIM][BIG_DIM], elem_t out[BIG_DIM][BIG_DIM]) {
 75:   for (size_t r = 0; r < BIG_DIM; r++)
 76:     for (size_t c = 0; c < BIG_DIM; c++)
 77:       out[r][c] = in[r][c] > 0 ? in[r][c] : 0;
 78: }
