144:               for (size_t b = 0; b < bytes; ++b) {
145:                 data |= (uint64_t)(rand() % 255) << (b*8);
146:               }
147: 
148:               In[i][j] = acc_t_bits_to_acc_t(data);
149:             } while (acc_t_isnan(In[i][j]));
150: #endif
151: 
152:             In_full[i][j] = In[i][j];
153:           }
154:         }
