171:             acc_t * dram_addr_in = &In[i][j];
172:             elem_t * dram_addr_out = &Out[i][j];
173:             uint32_t sp_addr = acc_addr + i*(BIG_DIM/DIM) + j;
174: 
175:             int already_moved_in = (j/DIM) % block_len != 0;
176: 
177:             if (!already_moved_in) {
178:               int len = j + block_len*DIM <= BIG_DIM ? block_len : (BIG_DIM-j)/DIM;
179:               // printf("Moving in with len: %d\n", len);
180:               gemmini_block_mvin(dram_addr_in, sp_addr, len);
181:               gemmini_mvout(dram_addr_out, sp_addr);
