 30: int is_equal_big(elem_t x[BIG_DIM][BIG_DIM], elem_t y[BIG_DIM][BIG_DIM]) {
 31:   for (size_t i = 0; i < BIG_DIM; ++i)
 32:     for (size_t j = 0; j < BIG_DIM; ++j)
