 64: #ifdef FAST
 65: #define RAND (j + i)
 66: #else
 67: #define RAND rand()
 68: #endif
 69:         In[i][j] = (RAND % 64) - 32; // i*BIG_DIM + j;
 70:         Out[i][j] = 0;
 71:       }
 72: 
 73:     gemmini_config_ld(BIG_DIM*sizeof(elem_t));
 74:     gemmini_config_st(BIG_DIM*sizeof(elem_t));
