20: 
21:   printf("Flush Gemmini TLB of stale virtual addresses\n");
22:   gemmini_flush(0);
23: 
24:   printf("Initialize our input and output matrices in main memory\n");
25:   elem_t In[DIM][DIM];
26:   elem_t Out[DIM][DIM];
27: 
28:   elem_t Identity[DIM][DIM];
29:   for (size_t i = 0; i < DIM; i++)
30:     for (size_t j = 0; j < DIM; j++)
31:       Identity[i][j] = i == j;
32: 
33:   printf("Calculate the scratchpad addresses of all our matrices\n");
34:   printf("  Note: The scratchpad is \"row-addressed\", where each address contains one matrix row\n");
35:   size_t In_sp_addr = 0;
36:   size_t Out_sp_addr = DIM;
37:   size_t Identity_sp_addr = 2*DIM;
38: 
39:   printf("Move \"In\" matrix from main memory into Gemmini's scratchpad\n");
40:   gemmini_config_ld(DIM * sizeof(elem_t));
41:   gemmini_config_st(DIM * sizeof(elem_t));
42:   gemmini_mvin(In, In_sp_addr);
43: 
44:   printf("Move \"Identity\" matrix from main memory into Gemmini's scratchpad\n");
45:   gemmini_mvin(Identity, Identity_sp_addr);
46: 
47:   printf("Multiply \"In\" matrix with \"Identity\" matrix with a bias of 0\n");
48:   gemmini_config_ex(OUTPUT_STATIONARY, 0, 0);
49:   gemmini_preload_zeros(Out_sp_addr);
50:   gemmini_compute_preloaded(In_sp_addr, Identity_sp_addr);
51: 
52:   printf("Move \"Out\" matrix from Gemmini's scratchpad into main memory\n");
53:   gemmini_config_st(DIM * sizeof(elem_t));
54:   gemmini_mvout(Out, Out_sp_addr);
55: 
56:   printf("Fence till Gemmini completes all memory operations\n");
57:   gemmini_fence();
58: 
59:   printf("Check whether \"In\" and \"Out\" matrices are identical\n");
60:   if (!is_equal(In, Out)) {
61:     printf("Input and output matrices are different!\n");
62:     printf("\"In\" matrix:\n");
63:     printMatrix(In);
64:     printf("\"Out\" matrix:\n");
65:     printMatrix(Out);
66:     printf("\n");
67: 
68:     exit(1);
69:   }
70: 
71:   printf("Input and output matrices are identical, as expected\n");
72:   exit(0);
