 70: void full_matscale(full_t full[MAT_DIM_I][MAT_DIM_J], elem_t out[MAT_DIM_I][MAT_DIM_J], acc_scale_t scale) {
 71:   for (size_t r = 0; r < MAT_DIM_I; r++)                             
 72:     for (size_t c = 0; c < MAT_DIM_J; c++) {
 73:       // Scale element
 74:       full_t scaled = ACC_SCALE(full[r][c], scale);
 75: 
 76:       // Saturate and cast element
 77: #ifndef ELEM_T_IS_FLOAT
 78:       full_t elem = scaled > elem_t_max ? elem_t_max : (scaled < elem_t_min ? elem_t_min : scaled);
 79:       out[r][c] = elem;
 80: #else
 81:       out[r][c] = scaled; // TODO should we also saturate when using floats?
 82: #endif
 83:     }
 84: } 
