135:     unsigned long start = read_cycles();
136: 
137:     tiled_matmul_auto(MAT_DIM_I, MAT_DIM_J, MAT_DIM_K,
138:             (elem_t*)full_A, (elem_t*)full_B, NO_BIAS ? NULL : &full_D[0][0], (elem_t*)full_C,
139:             MAT_DIM_K, MAT_DIM_J, MAT_DIM_J, MAT_DIM_J,
