123: #ifdef BAREMETAL
124:   for (enum tiled_matmul_type_t option = OS; option <= WS; option++) {
125:     for (int activation = 0; activation <= 1; activation++) {
126:       for (int scale = 0; scale <= 1; scale += 1) {
127: #else
128:   for (enum tiled_matmul_type_t option = OS; option <= CPU; option++) {
129:     for (int activation = 0; activation <= 2; activation++) {
130:       for (int scale = 0; scale <= 12; scale += 6) {
131: #endif
132:         for (int no_bias = 0; no_bias < 2; no_bias++) {
133:           for (int repeating_bias = 0; repeating_bias < 2; repeating_bias++) {
134:             for (int a_transpose = 0; a_transpose < 2; a_transpose++) {
135:               for (int b_transpose = 0; b_transpose < 2; b_transpose++) {
136: 
137:                 if (((option == OS || option == CPU) && (a_transpose || b_transpose)) ||
138:                   (option == WS && a_transpose && b_transpose)) {
139:                   continue;
140:                 }
141: 
142:                 static elem_t full_A[MAT_DIM_I][MAT_DIM_K] row_align(1);
143:                 static elem_t full_B[MAT_DIM_K][MAT_DIM_J] row_align(1);
144:                 static elem_t full_C[MAT_DIM_I][MAT_DIM_J] row_align(1);
145:                 static acc_t full_D[MAT_DIM_I][MAT_DIM_J] row_align_acc(1);
146: 
147:                 static full_t gold_full[MAT_DIM_I][MAT_DIM_J];
148:                 static elem_t gold[MAT_DIM_I][MAT_DIM_J];
149: 
150:                 // printf("Init A\n");
151:                 for (size_t i = 0; i < MAT_DIM_I; ++i) {
152:                   for (size_t j = 0; j < MAT_DIM_K; ++j) {
153:                     full_A[i][j] = (rand() % 3) - 1;
154:                   }
155:                 }
156: 
157:                 // printf("Init B\n");
158:                 for (size_t i = 0; i < MAT_DIM_K; ++i) {
159:                   for (size_t j = 0; j < MAT_DIM_J; ++j) {
160:                     full_B[i][j] = (rand() % 3) - 1;
161:                   }
162:                 }
163: 
164:                 // printf("Init D\n");
165:                 for (size_t i = 0; i < (repeating_bias ? 1 : MAT_DIM_I); ++i) {
166:                   for (size_t j = 0; j < MAT_DIM_J; ++j) {
167:                     full_D[i][j] = no_bias ? 0 : ((rand() % 3) - 1);
168:                   }
169:                 }
170: 
171: #pragma GCC diagnostic push
172: #pragma GCC diagnostic ignored "-Wincompatible-pointer-types"
173:                 printf("Starting CPU matmul\n");
174:                 if (!a_transpose && !b_transpose) {
175:                   full_matmul(full_A, full_B, full_D, gold_full, repeating_bias);
176:                 } else if (a_transpose && !b_transpose) {
177:                   full_matmul_At(full_A, full_B, full_D, gold_full, repeating_bias);
178:                 } else if (!a_transpose && b_transpose) {
179:                   full_matmul_Bt(full_A, full_B, full_D, gold_full, repeating_bias);
180:                 } else if (a_transpose && b_transpose) {
181:                   full_matmul_At_Bt(full_A, full_B, full_D, gold_full, repeating_bias);
182:                 }
183:                 full_matscale(gold_full, gold, scale);
184: #pragma GCC diagnostic pop
185: 
186:                 if (activation == RELU) {
187:                   full_matrelu(gold, gold);
188:                 }
189: 
190:                 size_t stride_A = a_transpose ? MAT_DIM_I : MAT_DIM_K;
191:                 size_t stride_B = b_transpose ? MAT_DIM_K : MAT_DIM_J;
192: 
193:                 printf("Starting gemmini matmul\n");
194:                 tiled_matmul_auto(MAT_DIM_I, MAT_DIM_J, MAT_DIM_K,
195:                         (elem_t*)full_A, (elem_t*)full_B, no_bias ? NULL : &full_D[0][0], (elem_t*)full_C,
196:                         stride_A, stride_B, MAT_DIM_J, MAT_DIM_J,
197:                         MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY,
198:                         activation, scale, 0, repeating_bias,
199:                         a_transpose, b_transpose,
200:                         false, false,
201:                         0,
202:                         option);
203: 
204:                 if (!full_is_equal(full_C, gold)) {
205:                   printf("\nINCORRECT!\n");
206:                   printf("option: %d\n", option);
207:                   printf("activation: %d\n", activation);
208:                   printf("scale: %d\n", scale);
209:                   printf("no_bias: %d\n", no_bias);
210:                   printf("repeating_bias: %d\n", repeating_bias);
211:                   printf("a_transpose: %d\n", a_transpose);
212:                   printf("b_transpose: %d\n", b_transpose);
213: 
214:                   printf("C:\n");
215:                   full_printMatrix(full_C);
216:                   printf("Gold:\n");
217:                   full_printMatrix(gold);
218:                   printf("Gold full:\n");
219:                   full_printMatrix64Bit(gold_full);
220:                   printf("\n");
221: 
222:                   exit(1);
223:                 }
224:               }
225:             }
226:           }
227:         }
228:       }
229:     }
230:   }
231: 
232:   exit(0);
