 35: void print_tile(elem_t* in, int tile_dim) {
 36:   for (size_t r = 0; r < tile_dim; r++) {
 37:     printf("row starts at: %p\n", in +r*MAT_DIM_J);
 38:     for (size_t c = 0; c < tile_dim; c++) {
 39:       printf("%d ", *(in +r*MAT_DIM_J + c));
 40:     }
 41:     printf("\n");
 42:   }
 43: }
