 45: void full_matmul(elem_t A[MAT_DIM_I][MAT_DIM_K], elem_t B[MAT_DIM_K][MAT_DIM_J], ACC_T D[MAT_DIM_I][MAT_DIM_J], full_t C_full[MAT_DIM_I][MAT_DIM_J]) {
 46:   for (size_t r = 0; r < MAT_DIM_I; r++)
 47:     for (size_t c = 0; c < MAT_DIM_J; c++) {
 48:       C_full[r][c] = D[r][c];
 49:       for (size_t k = 0; k < MAT_DIM_K; k++)
 50:         C_full[r][c] += A[r][k]*B[k][c];
 51:     }
 52: }
 53: 
 54: void full_printMatrix(elem_t m[MAT_DIM_I][MAT_DIM_J]) {
 55:   for (size_t i = 0; i < MAT_DIM_I; ++i) {
 56:     for (size_t j = 0; j < MAT_DIM_J; ++j)
 57:       printf("%d ", m[i][j]);
 58:     printf("\n");
 59:   }
 60: }
 61: 
 62: int full_is_equal(elem_t x[MAT_DIM_I][MAT_DIM_J], elem_t y[MAT_DIM_I][MAT_DIM_J]) {
 63:   for (size_t i = 0; i < MAT_DIM_I; ++i)
 64:     for (size_t j = 0; j < MAT_DIM_J; ++j)
 65:       if (x[i][j] != y[i][j])
 66:         return 0;
 67:   return 1;
 68: }
 69: 
 70: void full_matshift(full_t full[MAT_DIM_I][MAT_DIM_J], elem_t out[MAT_DIM_I][MAT_DIM_J], int shift) {
 71:   for (size_t r = 0; r < MAT_DIM_I; r++)                             
 72:     for (size_t c = 0; c < MAT_DIM_J; c++) {
 73:       // Bitshift and round element
 74:       full_t shifted = ROUNDING_RIGHT_SHIFT(full[r][c], shift);
 75: 
 76:       // Saturate and cast element
 77: #ifndef ELEM_T_IS_FLOAT
 78:       full_t elem = shifted > elem_t_max ? elem_t_max : (shifted < elem_t_min ? elem_t_min : shifted);
 79:       out[r][c] = elem;
 80: #else
 81:       out[r][c] = shifted; // TODO should we also saturate when using floats?
 82: #endif
 83:     }
 84: } 
