 34: void full_matmul(elem_t A[MAT_DIM_I][MAT_DIM_K], elem_t B[MAT_DIM_K][MAT_DIM_J], ACC_T D[MAT_DIM_I][MAT_DIM_J], acc_t C[MAT_DIM_I][MAT_DIM_J]) {
 35:   for (size_t r = 0; r < MAT_DIM_I; r++)
 36:     for (size_t c = 0; c < MAT_DIM_J; c++) {
 37:       C[r][c] = D[r][c];
 38:       for (size_t k = 0; k < MAT_DIM_K; k++)
 39:         C[r][c] += A[r][k]*B[k][c];
 40:     }
 41: }
