 51: int full_is_equal(acc_t x[MAT_DIM_I][MAT_DIM_J], acc_t y[MAT_DIM_I][MAT_DIM_J]) {
 52:   for (size_t i = 0; i < MAT_DIM_I; ++i)
 53:     for (size_t j = 0; j < MAT_DIM_J; ++j)
 54:       if (x[i][j] != y[i][j])
 55:         return 0;
 56:   return 1;
 57: }
