 34: void print_tile(elem_t* in, int tile_dim) {
 35:   for (size_t r = 0; r < tile_dim; r++) {
 36:     printf("row starts at: %p\n", in +r*MAT_DIM_J);
 37:     for (size_t c = 0; c < tile_dim; c++) {
 38:       printf("%d ", *(in +r*MAT_DIM_J + c));
 39:     }
 40:     printf("\n");
 41:   }
 42: }
