 44: void full_matmul(elem_t A[MAT_DIM_I][MAT_DIM_K], elem_t B[MAT_DIM_K][MAT_DIM_J], ACC_T D[MAT_DIM_I][MAT_DIM_J], full_t C_full[MAT_DIM_I][MAT_DIM_J]) {
 45:   for (size_t r = 0; r < MAT_DIM_I; r++)
 46:     for (size_t c = 0; c < MAT_DIM_J; c++) {
 47:       C_full[r][c] = D[r][c];
 48:       for (size_t k = 0; k < MAT_DIM_K; k++)
 49:         C_full[r][c] += A[r][k]*B[k][c];
 50:     }
 51: }
 52: 
 53: void full_printMatrix(elem_t m[MAT_DIM_I][MAT_DIM_J]) {
 54:   for (size_t i = 0; i < MAT_DIM_I; ++i) {
 55:     for (size_t j = 0; j < MAT_DIM_J; ++j)
 56:       printf("%d ", m[i][j]);
 57:     printf("\n");
 58:   }
 59: }
 60: 
 61: int full_is_equal(elem_t x[MAT_DIM_I][MAT_DIM_J], elem_t y[MAT_DIM_I][MAT_DIM_J]) {
 62:   for (size_t i = 0; i < MAT_DIM_I; ++i)
 63:     for (size_t j = 0; j < MAT_DIM_J; ++j)
 64:       if (x[i][j] != y[i][j])
 65:         return 0;
 66:   return 1;
 67: }
 68: 
 69: void full_matscale(full_t full[MAT_DIM_I][MAT_DIM_J], elem_t out[MAT_DIM_I][MAT_DIM_J], acc_scale_t scale) {
 70:   for (size_t r = 0; r < MAT_DIM_I; r++)                             
 71:     for (size_t c = 0; c < MAT_DIM_J; c++) {
 72:       // Scale element
 73:       full_t scaled = ACC_SCALE(full[r][c], scale);
 74: 
 75:       // Saturate and cast element
 76: #ifndef ELEM_T_IS_FLOAT
 77:       full_t elem = scaled > elem_t_max ? elem_t_max : (scaled < elem_t_min ? elem_t_min : scaled);
 78:       out[r][c] = elem;
 79: #else
 80:       out[r][c] = scaled; // TODO should we also saturate when using floats?
 81: #endif
 82:     }
 83: } 
