 85: int main() {
 86: #ifndef BAREMETAL
 87:     if (mlockall(MCL_CURRENT | MCL_FUTURE) != 0) {
 88:       perror("mlockall failed");
 89:       exit(1);
 90:     }
 91: #endif
 92: 
 93:     gemmini_flush(0);
 94: 
 95:     static elem_t full_A[MAT_DIM_I][MAT_DIM_K] row_align(1);
 96:     static elem_t full_B[MAT_DIM_K][MAT_DIM_J] row_align(1);
 97:     static elem_t full_C[MAT_DIM_I][MAT_DIM_J] row_align(1);
 98:     static ACC_T full_D[MAT_DIM_I][MAT_DIM_J] row_align_acc(1);
 99: 
100:     static full_t gold_full[MAT_DIM_I][MAT_DIM_J];
101:     static elem_t gold[MAT_DIM_I][MAT_DIM_J];
102: 
103: #if CHECK_RESULT == 1
104: #ifdef FAST
105: #define RAND 1
106: #else
107: #define RAND rand()
108: #endif
109:     // printf("Init A\n");
110:     for (size_t i = 0; i < MAT_DIM_I; ++i) {
111:       for (size_t j = 0; j < MAT_DIM_K; ++j) {
112:         full_A[i][j] = RAND % 2;
113:       }
114:     }
115: 
116:     // printf("Init B\n");
117:     for (size_t i = 0; i < MAT_DIM_K; ++i) {
118:       for (size_t j = 0; j < MAT_DIM_J; ++j) {
119:         full_B[i][j] = RAND % 2;
120:       }
121:     }
122: 
123:     // printf("Init D\n");
124:     for (size_t i = 0; i < MAT_DIM_I; ++i) {
125:       for (size_t j = 0; j < MAT_DIM_J; ++j) {
126:         full_D[i][j] = NO_BIAS ? 0 : RAND % 2;
127:       }
128:     }
129: 
130:     printf("Starting slow CPU matmul\n");
131:     unsigned long cpu_start = read_cycles();
132: #ifdef FAST
133:     for (size_t i = 0; i < MAT_DIM_I; ++i) {
134:       for (size_t j = 0; j < MAT_DIM_J; ++j) {
135:         gold_full[i][j] = MAT_DIM_K + (NO_BIAS ? 0 : (RAND % 2));
136:       }
137:     }
138: 
139: #else
140:     full_matmul(full_A, full_B, full_D, gold_full);
141: #endif
142:     unsigned long cpu_end = read_cycles();
143:     printf("Cycles taken: %u\n", cpu_end-cpu_start);
144:     full_matscale(gold_full, gold, ACC_SCALE_IDENTITY);
145: #endif
146: 
147:     printf("Starting gemmini matmul\n");
148:     unsigned long start = read_cycles();
149: 
150:     tiled_matmul_auto(MAT_DIM_I, MAT_DIM_J, MAT_DIM_K,
151:             (elem_t*)full_A, (elem_t*)full_B, NO_BIAS ? NULL : &full_D[0][0], (elem_t*)full_C,
152:             MAT_DIM_K, MAT_DIM_J, MAT_DIM_J, MAT_DIM_J,
153:             MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY,
154:             NO_ACTIVATION, ACC_SCALE_IDENTITY, 0, false,
155:             false, false,
156:             false, !FULL_BIAS_WIDTH,
157:             0,
158:             WS);
159: 
160:     unsigned long end = read_cycles();
161:     printf("Cycles taken: %u\n", end-start);
162: 
163: #if CHECK_RESULT == 1
164:     if (!full_is_equal(full_C, gold)) {
165:       printf("C:\n");
166:       full_printMatrix(full_C);
167:       printf("Gold:\n");
168:       full_printMatrix(gold);
169:       printf("\n");
170: 
171:       exit(1);
172:     }
173: #endif
174: 
175:   exit(0);
