137:             (elem_t*)full_A, (elem_t*)full_B, NO_BIAS ? NULL : &full_D[0][0], (elem_t*)full_C,
138:             MAT_DIM_K, MAT_DIM_J, MAT_DIM_J, MAT_DIM_J,
139:             MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY,
140:             NO_ACTIVATION, ACC_SCALE_IDENTITY, 0, false,
141:             false, false,
142:             false, !FULL_BIAS_WIDTH,
143:             0,
144:             WS);
145: 
146:     unsigned long end = read_cycles();
147:     printf("Cycles taken: %u\n", end-start);
148: 
149: 
150:     printf("Starting slow CPU matmul\n");
151:     unsigned long cpu_start = read_cycles();
152: #ifdef FAST
153:     for (size_t i = 0; i < MAT_DIM_I; ++i) {
154:       for (size_t j = 0; j < MAT_DIM_J; ++j) {
155:         gold_full[i][j] = MAT_DIM_K + (NO_BIAS ? 0 : (RAND % 2));
156:       }
157:     }
158: 
159: #else
160:     full_matmul(full_A, full_B, full_D, gold_full);
161: #endif
162:     unsigned long cpu_end = read_cycles();
163:     printf("Cycles taken: %u\n", cpu_end-cpu_start);
164:     full_matscale(gold_full, gold, ACC_SCALE_IDENTITY);
165: #endif
166: 
167: #if CHECK_RESULT == 1
168:     if (!full_is_equal(full_C, gold)) {
169:       printf("C:\n");
170:       full_printMatrix(full_C);
171:       printf("Gold:\n");
172:       full_printMatrix(gold);
173:       printf("\n");
174: 
175:       exit(1);
176:     }
177: #endif
178: 
179:   exit(0);
