50:   gemmini_extended_config_ex(OUTPUT_STATIONARY, 0, 0, 1, true, false)
51:   gemmini_preload_zeros(Out_sp_addr);
52:   gemmini_compute_preloaded(In_sp_addr, Identity_sp_addr);
53: 
54:   printf("Move \"Out\" matrix from Gemmini's scratchpad into main memory\n");
55:   gemmini_config_st(DIM * sizeof(elem_t));
56:   gemmini_mvout(Out, Out_sp_addr);
