 48: #define HIST_IMAGES(IMAGES) \
 49:     for (int num = -128; num <= 127; num++) { \
 50:         int count = 0; \
 51:         for (int i = 0; i < sizeof(IMAGES)/sizeof(IMAGES[0]); i++) { \
 52:             for (int j = 0; j < sizeof(IMAGES[0])/sizeof(IMAGES[0][0]); j++) { \
 53:                 for (int k = 0; k < sizeof(IMAGES[0][0])/sizeof(IMAGES[0][0][0]); k++) { \
 54:                     for (int l = 0; l < sizeof(IMAGES[0][0][0])/sizeof(IMAGES[0][0][0][0]); l++) { \
 55:                         if (IMAGES[i][j][k][l] == num) { \
 56:                             count++; \
 57:                         } \
 58:                     } \
 59:                 } \
 60:             } \
 61:         } \
 62:         if (count > 0) \
 63:             printf("%d: %d times\n", num, count); \
 64:     }
 65: 
