 80: // This function runs a tiled matrix multiplication, with explicit tiling
 81: // factors
 82: static void tiled_matmul_nn(size_t dim_I, size_t dim_J, size_t dim_K,
 83:         const elem_t A[dim_I][dim_K], const elem_t B[dim_K][dim_J],
 84:         const void * D, elem_t C[dim_I][dim_J],
 85:         int act, acc_scale_t scale, bool repeating_bias,
 86:         size_t tile_I, size_t tile_J, size_t tile_K,
 87:         enum tiled_matmul_type_t tiled_matmul_type,
 88:         bool check, char * layer_name)
 89: {
 90:     if (check)
 91:         printf("%s: gemmini\n", layer_name);
 92: 
 93:     tiled_matmul(dim_I, dim_J, dim_K,
 94:         (elem_t*)A, (elem_t*)B, D, (elem_t*)C, 
 95:         dim_K, dim_J, dim_J, dim_J,
 96:         MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY,
 97:         act, scale, 0, repeating_bias,
 98:         tile_I, tile_J, tile_K,
 99:         false, false,
100:         false, false,
101:         0,
102:         tiled_matmul_type);
103: 
104:     if (check) {
105:         printf("%s: CPU\n", layer_name);
106:         elem_t gold[dim_I][dim_J];
107:         tiled_matmul_auto(dim_I, dim_J, dim_K,
108:             (elem_t*)A, (elem_t*)B, D, (elem_t*)gold, 
109:             dim_K, dim_J, dim_J, dim_J,
110:             MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY,
111:             act, scale, 0, repeating_bias,
112:             false, false,
113:             false, false,
114:             0,
115:             CPU);
116: 
117:         if (!MAT_IS_EQUAL(dim_I, dim_J, C, gold)) {
118:             printf("Layer calculated incorrectly: %s\n", layer_name);
119:             exit(1);
120:         }
121:     }
122: }
