127: static void tiled_matmul_nn_auto(size_t dim_I, size_t dim_J, size_t dim_K, 
128:         const elem_t A[dim_I][dim_K], const elem_t B[dim_K][dim_J],
129:         const void * D, elem_t C[dim_I][dim_J],
130:         int act, acc_scale_t scale, bool repeating_bias,
131:         enum tiled_matmul_type_t tiled_matmul_type,
132:         bool check, char * layer_name)
