137:     tiled_matmul_auto(dim_I, dim_J, dim_K,
138:         (elem_t*)A, (elem_t*)B, D, (elem_t*)C,
139:         dim_K, dim_J, dim_J, dim_J,
140:         MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY,
141:         act, scale, 0, repeating_bias,
142:         false, false,
143:         false, false,
144:         0,
145:         tiled_matmul_type);
146: 
147:     if (check) {
148:         printf("%s: CPU\n", layer_name);
149:         elem_t gold[dim_I][dim_J];
150:         tiled_matmul_auto(dim_I, dim_J, dim_K,
151:             (elem_t*)A, (elem_t*)B, D, (elem_t*)gold, 
152:             dim_K, dim_J, dim_J, dim_J,
153:             MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY,
154:             act, scale, 0, repeating_bias,
155:             false, false,
156:             false, false,
157:             0,
158:             CPU);
159: 
160:         if (!MAT_IS_EQUAL(dim_I, dim_J, C, gold)) {
161:             printf("Layer calculated incorrectly: %s\n", layer_name);
162:             exit(1);
163:         }
164:     }
