167: // need to specify stride
168: // auto tiling calc
169: static void tiled_matmul_nn_stride_auto(size_t dim_I, size_t dim_J, size_t dim_K,
170:         const size_t A_stride, const size_t B_stride, const size_t C_stride,
171:         const elem_t * A, const elem_t * B, const void * D, const elem_t * C,
172:         int act, acc_scale_t scale, bool repeating_bias,
173:         enum tiled_matmul_type_t tiled_matmul_type)
174: {
175: 
176:     tiled_matmul_auto(dim_I, dim_J, dim_K,
177:         (elem_t*)A, (elem_t*)B, D, (elem_t*)C,
178:         A_stride, B_stride, C_stride, C_stride,
179:         MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY,
180:         act, scale, 0, repeating_bias,
181:         false, false,
182:         false, false,
183:         0,
184:         tiled_matmul_type);
