186: static void conv_dw(size_t I, size_t J,
187:     const size_t batch_size, const size_t channels,
188:     const size_t in_row_dim, const size_t in_col_dim,
189:     const size_t out_row_dim, const size_t out_col_dim,
190:     const size_t kernel_size,
191:     const elem_t input[batch_size][in_row_dim][in_col_dim][channels],
192:     const elem_t weight[channels][kernel_size][kernel_size],
193:     const acc_t * bias,
194:     // elem_t output [batch_size][out_row_dim][out_col_dim][channels],
195:     elem_t output [I][J],
196:     const struct ConvParams * params)
197: {
198:     for (int batch = 0; batch < batch_size; batch++) {
199:         for (int channel = 0; channel < channels; channel++) {
200:             for (int out_row = 0; out_row < out_row_dim; out_row++) {
201:                 for (int out_col = 0; out_col < out_col_dim; out_col++) {
202:                     int in_row = out_row * params->stride - params->padding;
203: 
204:                     acc_t result = 0;
205:                     if (params->bias) {
206:                         result = bias[channel];
207:                     }
208: 
209:                     for (int kernel_row = 0; kernel_row < params->kernel_size; kernel_row++) {
210:                         int in_col = out_col * params->stride - params->padding;
211: 
212:                         for (int kernel_col = 0; kernel_col < params->kernel_size; kernel_col++) {
213:                             if (in_row >= 0 && in_row < params->in_row_dim && in_col >= 0 && in_col < params->in_col_dim) {
214:                                 result += input[batch][in_row][in_col][channel] * weight[channel][kernel_row][kernel_col];
215:                             }
216: 
217:                             in_col++;
218:                         }
219: 
220:                         in_row++;
221:                     }
222: 
223:                     if (result < 0) {
224:                         result = 0;
225:                     }
226:                     
227:                     acc_t scaled = ACC_SCALE(result, params->output_scale);
228: 
229:                     if (scaled > elem_t_max) {
230:                         scaled = elem_t_max;
231:                     } else if (scaled < elem_t_min) {
232:                         scaled = elem_t_min;
233:                     }
234:                     
235:                     size_t r = batch * params->out_row_dim * params->out_col_dim + out_row * params->out_col_dim + out_col;
236:                     output[r][channel] = scaled;
237:                     // output[batch][out_row][out_col][channel] = scaled;
238:                 }
239:             }
240:         }
241:     }
242: }
