244: static void conv_dw_with_col2im(size_t prev_I, size_t prev_J, size_t I, size_t J,
245:     const size_t batch_size, const size_t channels,
246:     const size_t out_row_dim, const size_t out_col_dim, const size_t kernel_size,
247:     const elem_t input[prev_I][prev_J],
248:     const elem_t weight[channels][kernel_size][kernel_size],
249:     const acc_t * bias,
250:     // elem_t output [batch_size][out_dim][out_dim][channels],
251:     elem_t output [I][J],
252:     const struct ConvParams * params)
253: {
254:     for (int batch = 0; batch < batch_size; batch++) {
255:         for (int channel = 0; channel < channels; channel++) {
256:             for (int out_row = 0; out_row < out_row_dim; out_row++) {
257:                 for (int out_col = 0; out_col < out_col_dim; out_col++) {
258:                     int in_row = out_row * params->stride - params->padding;
259: 
260:                     acc_t result = 0;
261:                     if (params->bias) {
262:                         result = bias[channel];
263:                     }
264: 
265:                     for (int kernel_row = 0; kernel_row < params->kernel_size; kernel_row++) {
266:                         int in_col = out_col * params->stride - params->padding;
267: 
268:                         for (int kernel_col = 0; kernel_col < params->kernel_size; kernel_col++) {
269:                             if (in_row >= 0 && in_row < params->in_row_dim && in_col >= 0 && in_col < params->in_col_dim) {
270:                                 // result += input[batch][in_row][in_col][channel] * weight[channel][kernel_row][kernel_col];
271: 
272:                                 size_t r = batch * params->in_row_dim * params->in_col_dim + in_row * params->in_col_dim + in_col;
273: 
274:                                 result += input[r][channel] * weight[channel][kernel_row][kernel_col];
275:                             }
276: 
277:                             in_col++;
278:                         }
279: 
280:                         in_row++;
281:                     }
282: 
283:                     if (result < 0) {
284:                         result = 0;
285:                     }
286:                     
287:                     acc_t scaled = ACC_SCALE(result, params->output_scale);
288: 
289:                     if (scaled > elem_t_max) {
290:                         scaled = elem_t_max;
291:                     } else if (scaled < elem_t_min) {
292:                         scaled = elem_t_min;
293:                     }
294:                     
295:                     size_t r = batch * params->out_row_dim * params->out_col_dim + out_row * params->out_col_dim + out_col;
296:                     output[r][channel] = scaled;
297:                     // output[batch][out_row][out_col][channel] = scaled;
298:                 }
299:             }
300:         }
301:     }
302: }
