304: static void im2col(size_t batch_size, size_t channels, size_t im_row_dim, size_t im_col_dim,
305:     size_t I, size_t K,
306:     const elem_t input[batch_size][im_row_dim][im_col_dim][channels],
307:     elem_t output[I][K],
308:     const struct ConvParams * params)
309: {
310:     int patch_row = 0;
311: 
312:     for (int n_batch = 0; n_batch < params->batch_size; n_batch++) {
313:         for (int im_row = -params->padding; im_row < params->in_row_dim - params->kernel_size + params->padding + 1; im_row += params->stride) {
314:             for (int im_col = -params->padding; im_col < params->in_col_dim - params->kernel_size + params->padding + 1; im_col += params->stride) {
315:                 int patch_col = 0;
316: 
317:                 for (int filter_row = 0; filter_row < params->kernel_size; filter_row++) {
318:                     for (int filter_col = 0; filter_col < params->kernel_size; filter_col++) {
319:                         for (int im_channel = 0; im_channel < params->in_channels; im_channel++) {
320:                             int pixel_row = im_row + filter_row;
321:                             int pixel_col = im_col + filter_col;
322:                             
323:                             if (pixel_row < 0 || pixel_row >= params->in_row_dim
324:                                 || pixel_col < 0 || pixel_col >= params->in_col_dim) {
325:                                 // output[patch_row][patch_col] = 0;
326:                             } else {
327:                                 output[patch_row][patch_col] = input[n_batch][pixel_row][pixel_col][im_channel];
328:                             }
329: 
330:                             patch_col++;
331:                         }
332:                     }
333:                 }
334:                 
335:                 patch_row++;
336:             }
337:         }
338:     }
339: }
