341: static void im2col_with_col2im(size_t prev_I, size_t prev_J,
342:     size_t next_I, size_t next_K,
343:     const elem_t input[prev_I][prev_J],
344:     elem_t output[next_I][next_K],
345:     const struct ConvParams * params)
346: {
347:     int out_row = 0;
348: 
349:     for (int n_batch = 0; n_batch < params->batch_size; n_batch++) {
350:         for (int im_row = -params->padding; im_row < params->in_row_dim - params->kernel_size + params->padding + 1; im_row += params->stride) {
351:             for (int im_col = -params->padding; im_col < params->in_col_dim - params->kernel_size + params->padding + 1; im_col += params->stride) {
352:                 int out_col = 0;
353: 
354:                 for (int filter_row = 0; filter_row < params->kernel_size; filter_row++) {
355:                     for (int filter_col = 0; filter_col < params->kernel_size; filter_col++) {
356:                         for (int im_channel = 0; im_channel < params->in_channels; im_channel++) {
357:                             int pixel_row = im_row + filter_row;
358:                             int pixel_col = im_col + filter_col;
359: 
360:                             if (pixel_row < 0 || pixel_row >= params->in_row_dim
361:                                 || pixel_col < 0 || pixel_col >= params->in_col_dim) {
362:                                 // output[out_row][out_col] = 0;
363:                             } else {
364:                                 int in_row = n_batch * params->in_row_dim * params->in_col_dim + pixel_row * params->in_col_dim + pixel_col;
365:                                 int in_col = im_channel;
366: 
367:                                 output[out_row][out_col] = input[in_row][in_col];
368:                             }
369: 
370:                             out_col++;
371:                         }
372:                     }
373:                 }
374: 
375:                 out_row++;
376:             }
377:         }
378:     }
379: }
