381: // Compute C = A + B with saturating add
382: void vecadd(size_t len, const elem_t * A, const elem_t * B, elem_t * C, scale_t A_shift) {
383:     for (size_t i = 0; i < len; i++) {
384:         acc_t result = MVIN_SCALE(A[i], A_shift) + B[i];
385: 
386:         if (result > elem_t_max) {
387:             result = elem_t_max;
388:         } else if (result < elem_t_min) {
389:             result = elem_t_min;
390:         }
391: 
392:         C[i] = result;
393:     }
394: }
