396: void resadd1(const size_t batch_size, const size_t channels, const size_t im_dim,
397:     const elem_t A[batch_size][im_dim][im_dim][channels],
398:     const elem_t B[batch_size][im_dim][im_dim][channels],
399:     elem_t C[batch_size][im_dim][im_dim][channels],
400:     bool relu,
401:     const struct ConvParams * params) {
402: 
403:     const int minimum = relu ? 0 : elem_t_min;
404: 
405:     for (size_t batch = 0; batch < params->batch_size; batch++) {
406:         for (size_t row = 0; row < params->out_dim_pooled; row++) {
407:             for (size_t col = 0; col < params->out_dim_pooled; col++) {
408:                 for (size_t channel = 0; channel < params->out_channels; channel++) {
409:                     acc_t result = MVIN_SCALE(A[batch][row][col][channel], params->res_scale) + B[batch][row][col][channel];
410: 
411:                     if (result > elem_t_max) {
412:                         result = elem_t_max;
413:                     } else if (result < minimum) {
414:                         result = minimum;
415:                     }
416: 
417:                     C[batch][row][col][channel] = result;
418:                 }
419:             }
420:         }
421:     }
422: }
