485: // Pooling
486: void pool(size_t batch_size, size_t channels, size_t in_row_dim, size_t in_col_dim,
487:     size_t out_row_dim, size_t out_col_dim,
488:     elem_t input[batch_size][in_row_dim][in_col_dim][channels],
489:     elem_t output[batch_size][out_row_dim][out_col_dim][channels],
490:     const struct ConvParams * params)
491: {
492:     size_t kernel_size = params->pool_size;
493:     size_t stride = params->pool_stride;
494:     // size_t in_dim = params->out_dim;
495:     size_t padding = params->pool_padding;
496: 
497:     for (int batch = 0; batch < batch_size; batch++) {
498:         for (int channel = 0; channel < channels; channel++) {
499:             for (int out_row = 0; out_row < out_row_dim; out_row++) {
500:                 for (int out_col = 0; out_col < out_col_dim; out_col++) {
501:                     int in_row = out_row * stride - padding;
502: 
503:                     elem_t result = elem_t_min;
504: 
505:                     for (int kernel_row = 0; kernel_row < kernel_size; kernel_row++) {
506:                         int in_col = out_col * stride - padding;
507: 
508:                         for (int kernel_col = 0; kernel_col < kernel_size; kernel_col++) {
509:                             if (in_row >= 0 && in_row < in_row_dim && in_col >= 0 && in_col < in_col_dim) {
510:                                 if (input[batch][in_row][in_col][channel] > result) {
511:                                     result = input[batch][in_row][in_col][channel];
512:                                 }
513:                             } else if (0 > result) {
514:                                 result = 0;
515:                             }
516: 
517:                             in_col++;
518:                         }
519: 
520:                         in_row++;
521:                     }
522:                     
523:                     output[batch][out_row][out_col][channel] = result;
524:                 }
525:             }
526:         }
527:     }
528: }
