40: // Rounding right shift equation: https://riscv.github.io/documents/riscv-v-spec/#_vector_fixed_point_rounding_mode_register_vxrm
41: #define ROUNDING_RIGHT_SHIFT(x, shift) \
42:     ((shift) > 0 ? (((x) >> (shift)) + \
43:         (((shift) == 0 ? 0 : (((x) >> ((shift)-1)) & 1)) & \
44:              ((((shift) <= 1 ? 0 : ((x) & ((1 << ((shift)-1)) - 1))) != 0) | (((x) >> (shift)) & 1)))) : ((x) << (-(shift))))
45: 
46: #ifdef __cplusplus
47: #define SAME_TYPE(x) decltype(x)
48: #else
49: #define SAME_TYPE(x) typeof(x)
50: #endif
51: 
52: #define ROUND_NEAR_EVEN(x) \
53:     ({ const SAME_TYPE(x) x_ = (x); \
54:          const long long i = x_; \
55:          const long long next = x_ < 0 ? x_ - 1 : x_ + 1; \
56:          SAME_TYPE(x) rem = x_ - i; \
57:          rem = rem < 0 ? -rem : rem; \
58:          SAME_TYPE(x) result = rem < 0.5 ? i : (rem > 0.5 ? next : ( \
59:                      i % 2 == 0 ? i : next)); \
60:          result; })
61: 
62: // Rounding right shift equation: https://riscv.github.io/documents/riscv-v-spec/#_vector_fixed_point_rounding_mode_register_vxrm
63: #define ROUNDING_RIGHT_SHIFT_BITS(x, shift) \
64: ((shift) > 0 ? (((x) >> (shift)) + \
65:     (((shift) == 0 ? 0 : (((x) >> ((shift)-1)) & 1)) & \
66:          ((((shift) <= 1 ? 0 : ((x) & ((1 << ((shift)-1)) - 1))) != 0) | (((x) >> (shift)) & 1)))) : ((x) << (-(shift))))
67: 
68: #define ACC_SCALE(x, scale) \
69:     ({float y = ROUND_NEAR_EVEN((x) * (scale)); y > INT8_MAX ? INT8_MAX : (y < INT8_MIN ? INT8_MIN : (acc_t)y);})
70: 
71: #define MVIN_SCALE(x, scale) \
72:     ({float y = ROUND_NEAR_EVEN((x) * (scale)); y > INT8_MAX ? INT8_MAX : (y < INT8_MIN ? INT8_MIN : (elem_t)y);})
73: 
74: #define MVIN_SCALE_ACC(x, scale) (x)
