 29: // Matmul utility functions
 30: static void matmul(elem_t A[DIM][DIM], elem_t B[DIM][DIM], elem_t D[DIM][DIM], full_t C_full[DIM][DIM]) {
 31:   for (size_t r = 0; r < DIM; r++)
 32:     for (size_t c = 0; c < DIM; c++) {
 33:       C_full[r][c] = D[r][c];
 34:       for (size_t k = 0; k < DIM; k++)
 35:         C_full[r][c] += A[r][k]*B[k][c];
 36:     }
 37: }
 38: 
 39: static void matmul_short(elem_t A[DIM][DIM], elem_t B[DIM][DIM], elem_t D[DIM][DIM], elem_t C[DIM][DIM]) {
 40:   for (size_t r = 0; r < DIM; r++)
 41:     for (size_t c = 0; c < DIM; c++) {
 42:       C[r][c] = D[r][c];
 43:       for (size_t k = 0; k < DIM; k++)
 44:         C[r][c] += A[r][k]*B[k][c];
 45:     }
 46: }
 47: 
 48: static void matmul_full(elem_t A[DIM][DIM], elem_t B[DIM][DIM], full_t D[DIM][DIM], full_t C_full[DIM][DIM]) {
 49:   // Identical to the other matmul function, but with a 64-bit bias
 50:   for (size_t r = 0; r < DIM; r++)
 51:     for (size_t c = 0; c < DIM; c++) {
 52:       C_full[r][c] = D[r][c];
 53:       for (size_t k = 0; k < DIM; k++)
 54:         C_full[r][c] += A[r][k]*B[k][c];
 55:     }
