145: // THIS IS A ROUNDING SHIFT! It also performs a saturating cast
146: static void matshift(full_t full[DIM][DIM], elem_t out[DIM][DIM], int shift) {
147:   for (size_t r = 0; r < DIM; r++)
148:     for (size_t c = 0; c < DIM; c++) {
149:       // Bitshift and round element
150:       full_t shifted = ROUNDING_RIGHT_SHIFT(full[r][c], shift);
151: 
152:       // Saturate and cast element
153: #ifndef ELEM_T_IS_FLOAT
154:       full_t elem = shifted > elem_t_max ? elem_t_max : (shifted < elem_t_min ? elem_t_min : shifted);
155:       out[r][c] = elem;
156: #else
157:       out[r][c] = shifted; // TODO should we also saturate when using floats?
158: #endif
159:     }
160: }
161: 
162: static void matscale(full_t full[DIM][DIM], elem_t out[DIM][DIM], acc_scale_t scale) {
163:   for (size_t r = 0; r < DIM; r++)
164:     for (size_t c = 0; c < DIM; c++) {
165:       // Bitshift and round element
166:       full_t scaled = ACC_SCALE(full[r][c], scale);
167: 
168:       // Saturate and cast element
169: #ifndef ELEM_T_IS_FLOAT
170:       full_t elem = scaled > elem_t_max ? elem_t_max : (scaled < elem_t_min ? elem_t_min : scaled);
171:       out[r][c] = elem;
172: #else
173:       out[r][c] = scaled; // TODO should we also saturate when using floats?
174: #endif
175:     }
176: }
177: 
178: static void matrelu(elem_t in[DIM][DIM], elem_t out[DIM][DIM]) {
179:   for (size_t r = 0; r < DIM; r++)
180:     for (size_t c = 0; c < DIM; c++)
181:       out[r][c] = in[r][c] > 0 ? in[r][c] : 0;
182: }
183: 
184: static void transpose(elem_t in[DIM][DIM], elem_t out[DIM][DIM]) {
185:   for (size_t r = 0; r < DIM; r++)
186:     for (size_t c = 0; c < DIM; c++)
187:       out[c][r] = in[r][c];
188: }
