229: static int is_equal(elem_t x[DIM][DIM], elem_t y[DIM][DIM]) {
230:   for (size_t i = 0; i < DIM; ++i)
231:     for (size_t j = 0; j < DIM; ++j) {
232: #ifndef ELEM_T_IS_FLOAT
233:       if (x[i][j] != y[i][j])
234: #else
235:       bool isnanx = elem_t_isnan(x[i][j]);
236:       bool isnany = elem_t_isnan(y[i][j]);
237: 
238:       if (x[i][j] != y[i][j] && !(isnanx && isnany))
239: #endif
240:           return 0;
241:     }
242:   return 1;
243: }
244: 
245: static int is_equal_transposed(elem_t x[DIM][DIM], elem_t y[DIM][DIM]) {
246:   for (size_t i = 0; i < DIM; ++i)
247:     for (size_t j = 0; j < DIM; ++j) {
248: #ifndef ELEM_T_IS_FLOAT
249:       if (x[i][j] != y[j][i])
250: #else
251:       bool isnanx = elem_t_isnan(x[i][j]);
252:       bool isnany = elem_t_isnan(y[j][i]);
253: 
254:       if (x[i][j] != y[j][i] && !(isnanx && isnany))
255: #endif
256:           return 0;
257:     }
258:   return 1;
259: }
