262: #define MAT_IS_EQUAL(dim_i, dim_j, x, y) \
263:     ({int result = 1; \
264:       for (size_t i = 0; i < dim_i; i++) \
265:         for (size_t j = 0; j < dim_j; ++j) { \
266:           if (x[i][j] != y[i][j]) { \
267:             result = 0; \
268:             break; \
269:           } \
270:         } \
271:       result;})
