 120: static bool elem_t_isnan(elem_t x) {
 121:     elem_t_bits bits = elem_t_to_elem_t_bits(x);
 122:     uint64_t exp = (bits >> (ELEM_T_SIG_BITS-1)) & (((uint64_t)1 << ELEM_T_EXP_BITS) - 1);
 123:     uint64_t sig = bits & (((uint64_t)1 << ELEM_T_SIG_BITS) - 1);
 124:     bool is_nan_or_inf = exp == (((uint64_t)1 << ELEM_T_EXP_BITS) - 1);
 125:     bool is_not_inf = sig != 0;
 126:     return is_nan_or_inf && is_not_inf;
 127: }
 128: 
 129: static bool acc_t_isnan(acc_t x) {
 130:     acc_t_bits bits = acc_t_to_acc_t_bits(x);
 131:     uint64_t exp = (bits >> (ACC_T_SIG_BITS-1)) & (((uint64_t)1 << ACC_T_EXP_BITS) - 1);
 132:     uint64_t sig = bits & (((uint64_t)1 << ACC_T_SIG_BITS) - 1);
 133:     bool is_nan_or_inf = exp == (((uint64_t)1 << ACC_T_EXP_BITS) - 1);
 134:     bool is_not_inf = sig != 0;
 135:     return is_nan_or_inf && is_not_inf;
 136: }
