 311: // Counter access
 312: #define gemmini_counter_access(rd, config_reg) \
 313:   { \
 314:     uint32_t _placeholder; \
 315:     ROCC_INSTRUCTION(XCUSTOM_ACC, rd, config_reg, _placeholder, k_COUNTER) \
 316:   }
 317: 
 318: // Read counter
 319: static uint32_t counter_read(size_t index) {
 320:   uint32_t config_reg = (index & 0x7) << 4;
 321:   uint32_t res;
 322:   gemmini_counter_access(res, config_reg);
 323:   return res;
 324: }
 325: 
 326: // Configure counter to take a new signal
 327: static void counter_configure(size_t index, size_t counter_code) {
 328:   int non_incremental = counter_code > INCREMENTAL_COUNTERS;
 329:   if (non_incremental) {
 330:     counter_code -= INCREMENTAL_COUNTERS;
 331:   }
 332: 
 333:   uint32_t config_reg = (index & 0x7) << 4 | 0x8 | (counter_code & 0x3f) << 12 | non_incremental << 31;
 334:   uint32_t placeholder;
 335:   gemmini_counter_access(placeholder, config_reg);
 336: }
 337: 
 338: // Take a snapshot
 339: static void counter_snapshot_take() {
 340:   uint32_t config_reg = 0x4;
 341:   uint32_t placeholder;
 342:   gemmini_counter_access(placeholder, config_reg);
 343: }
 344: 
 345: // Counter snapshot reset
 346: static void counter_snapshot_reset() {
 347:   uint32_t config_reg = 0x2;
 348:   uint32_t placeholder;
 349:   gemmini_counter_access(placeholder, config_reg);
 350: }
 351: 
 352: // Counter module reset
 353: static void counter_reset() {
 354:   uint32_t config_reg = 0x1;
 355:   uint32_t placeholder;
 356:   gemmini_counter_access(placeholder, config_reg);
 357: }
