1787: static int tiled_conv_total_spad_rows_dw(bool acc, bool weight,
1788:         int stride,
1789:         int batches,
1790:         int porows, int pocols, int ochs,
1791:         int krows, int kcols, int kchs,
1792:         int pool_size, int pool_stride) {
1793: 
1794:     const int orows = porows * pool_stride + pool_size - 1;
1795:     const int ocols = pocols * pool_stride + pool_size - 1;
1796: 
1797:     const int irows = orows * stride + krows - 1; // - 2 * padding;
1798:     const int icols = ocols * stride + kcols - 1; // - 2 * padding;
1799:     const int ichs = kchs;
1800: 
1801:     const int in_channels_per_bank = ichs / DIM + (ichs % DIM != 0);
1802:     const int out_channels_per_bank = ochs / DIM + (ochs % DIM != 0);
1803: 
1804:     const int A_rows = in_channels_per_bank * batches * irows * icols;
1805:     const int B_rows = out_channels_per_bank * kcols * krows * kchs;
1806:     const int C_rows = out_channels_per_bank * batches * orows * ocols;
1807: 
1808:     if (acc)
1809:         return C_rows;
1810:     else if(weight)
1811:         return B_rows;
1812:     else
1813:         return A_rows;
1814: }
