1817: static int tiled_conv_total_spad_rows(bool acc,
1818:         int stride,
1819:         int input_dilation,
1820:         int kernel_dilation,
1821:         bool downsample,
1822:         bool trans_weight_0132,
1823:         bool trans_input_3120,
1824:         int batches,
1825:         int porows, int pocols, int ochs,
1826:         int krows, int kcols, int kchs,
1827:         int pool_size, int pool_stride) {
1828: 
1829:     const int orows = porows * pool_stride + pool_size - 1;
1830:     const int ocols = pocols * pool_stride + pool_size - 1;
1831: 
1832:     const int krows_dilated = krows + (kernel_dilation - 1)*(krows - 1);
1833:     const int kcols_dilated = kcols + (kernel_dilation - 1)*(kcols - 1);
1834: 
1835:     int irows = orows * stride + krows_dilated - 1; // - 2 * padding;
1836:     int icols = ocols * stride + kcols_dilated - 1; // - 2 * padding;
1837:     const int ichs = kchs;
1838: 
1839:     irows = irows / input_dilation + (irows % input_dilation != 0);
1840:     icols = icols / input_dilation + (icols % input_dilation != 0);
1841: 
1842:     const int in_channels_per_bank = ichs / DIM + (ichs % DIM != 0);
1843:     const int out_channels_per_bank = ochs / DIM + (ochs % DIM != 0);
1844:     const int batches_per_bank = batches / DIM + (batches % DIM != 0);
1845: 
1846:     const int A_rows = trans_input_3120 ?
1847:         (batches_per_bank * ichs * (irows >> downsample) * (icols >> downsample)) :
1848:         (in_channels_per_bank * batches * (irows >> downsample) * (icols >> downsample));
1849: 
1850:     const int B_rows = trans_weight_0132 ?
1851:       in_channels_per_bank * kcols * krows * ochs :
1852:       out_channels_per_bank * kcols * krows * kchs;
1853: 
1854:     const int C_rows = out_channels_per_bank * batches * orows * ocols;
1855: 
1856:     return acc ? C_rows : A_rows + B_rows;
1857: }
1858: 
1859: 
1860: static void conv_cpu_without_pool(
1861:         int batch_size, int in_row_dim, int in_col_dim, int in_channels,
1862:         int out_channels, int out_row_dim, int out_col_dim,
1863:         int stride, int input_dilation, int kernel_dilation, int padding, int kernel_dim,
1864:         int in_stride, int weight_stride, int out_stride,
1865:         bool wrot180, bool trans_output_1203, bool trans_input_3120,
1866:         bool trans_weight_1203, bool trans_weight_0132,
1867: 
1868:         const elem_t * input,
1869:         const elem_t * weights,
1870:         const acc_t * bias,
1871:         elem_t * output,
1872: 
1873:         int act, acc_scale_t scale) {
1874: 
1875:   bool no_bias = bias == NULL;
1876: 
1877:   for (int b = 0; b < batch_size; b++) {
1878:     for (int orow = 0; orow < out_row_dim; orow++) {
1879:       for (int ocol = 0; ocol < out_col_dim; ocol++) {
1880:         for (int och = 0; och < out_channels; och++) {
1881: 
1882:           acc_t opixel = no_bias ? 0 : bias[och];
1883: 
1884:           for (int krow = 0; krow < kernel_dim; krow++) {
1885:             if ((orow * stride + krow * kernel_dilation - padding) % input_dilation != 0)
1886:               continue;
1887: 
1888:             const int irow = (orow * stride + krow * kernel_dilation - padding) / input_dilation;
1889: 
1890:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
1891:               if ((ocol * stride + kcol * kernel_dilation - padding) % input_dilation != 0)
1892:                 continue;
1893: 
1894:               const int icol = (ocol * stride + kcol * kernel_dilation - padding) / input_dilation;
1895: 
1896:               for (int kch = 0; kch < in_channels; kch++) {
1897:                 const elem_t *in = input + (b * in_row_dim * in_col_dim + irow * in_col_dim + icol) * in_stride + kch;
1898:                 if (trans_input_3120) {
1899:                   // NHWC to CHWN
1900:                   in = input + (kch * in_row_dim * in_col_dim + irow * in_col_dim + icol) * batch_size + b;
1901:                 }
1902: 
1903:                 elem_t ipixel = irow < 0 || irow >= in_row_dim || icol < 0 || icol >= in_col_dim ?
1904:                     0 : *in;
1905: 
1906:                 const int krow_ = wrot180 ? kernel_dim - krow - 1 : krow;
1907:                 const int kcol_ = wrot180 ? kernel_dim - kcol - 1 : kcol;
1908: 
1909:                 elem_t weight = *(weights + (krow_ * kernel_dim * in_channels + kcol_ * in_channels + kch) * weight_stride + och);
1910:                 if (trans_weight_1203) {
1911:                   // HWIO to WIHO
1912:                   weight = *(weights + (kch * kernel_dim * kernel_dim  + krow_ * kernel_dim + kcol_) * out_channels + och);
1913:                 } else if (trans_weight_0132) {
1914:                   // HWIO to HWOI
1915:                   weight = *(weights + (krow_ * kernel_dim * out_channels + kcol_ * out_channels + och) * in_channels + kch);
1916:                 }
1917: 
1918:                 opixel += weight * ipixel;
1919:               }
1920:             }
1921:           }
1922: 
1923:           elem_t *out = output + (b * out_row_dim * out_col_dim + orow * out_col_dim + ocol) * out_stride + och;
1924:           if (trans_output_1203) {
1925:             // NHWC to HWNC
1926:             out = output + (orow * out_col_dim * batch_size + ocol * batch_size + b) * out_channels + och;
1927:           }
1928: 
1929:           *out = scale_and_sat(opixel, act, scale, 0);
1930:         }
1931:       }
1932:     }
1933:   }
1934: }
1935: 
1936: 
1937: static void conv_dw_cpu_without_pool(
1938:         int batch_size, int in_row_dim, int in_col_dim,
1939:         int channels, int out_row_dim, int out_col_dim,
1940:         int stride, int padding, int kernel_dim,
1941: 
1942:         const elem_t * input,
1943:         const elem_t * weights,
1944:         const acc_t * bias,
1945:         elem_t * output,
1946: 
1947:         int act, acc_scale_t scale) {
1948: 
1949:   bool no_bias = bias == NULL;
1950: 
1951:   for (int b = 0; b < batch_size; b++) {
1952:     for (int orow = 0; orow < out_row_dim; orow++) {
1953:       for (int ocol = 0; ocol < out_col_dim; ocol++) {
1954:         for (int ch = 0; ch < channels; ch++) {
1955:           acc_t opixel = no_bias ? 0 : bias[ch];
1956: 
1957:           for (int krow = 0; krow < kernel_dim; krow++) {
1958:             const int irow = orow * stride + krow - padding;
1959: 
1960:             for (int kcol = 0; kcol < kernel_dim; kcol++) {
1961:               const int icol = ocol * stride + kcol - padding;
1962: 
1963:               const elem_t * in = input + (b * in_row_dim * in_col_dim + irow * in_col_dim + icol) * channels + ch;
1964: 
1965:               const elem_t ipixel = irow < 0 || irow >= in_row_dim || icol < 0 || icol >= in_col_dim ?
1966:                   0 : *in;
1967: 
1968:               const elem_t weight = *(weights + (ch * kernel_dim + krow) * kernel_dim  + kcol);
1969: 
1970:               opixel += weight * ipixel;
1971:             }
1972:           }
1973: 
1974:           elem_t *out = output + (b * out_row_dim * out_col_dim + orow * out_col_dim + ocol) * channels + ch;
1975: 
1976:           *out = scale_and_sat(opixel, act, scale, 0);
1977:         }
1978:       }
1979:     }
1980:   }
1981: }
