1984: static void conv_cpu(
1985:         int batch_size, int in_row_dim, int in_col_dim, int in_channels,
1986:         int out_channels, int out_row_dim, int out_col_dim,
1987:         int stride, int input_dilation, int kernel_dilation, int padding, int kernel_dim,
1988:         int in_stride, int weight_stride, int out_stride,
1989:         bool wrot180, bool trans_output_1203, bool trans_input_3120,
1990:         bool trans_weight_1203, bool trans_weight_0132,
1991: 
1992:         const elem_t * input,
1993:         const elem_t * weights,
1994:         const acc_t * bias,
1995:         elem_t * output,
1996: 
1997:         int act, acc_scale_t scale,
1998:         int pool_size, int pool_stride, int pool_padding) {
1999: 
2000:   const bool no_pool = pool_stride == 0;
2001:   if (no_pool) {
2002:     conv_cpu_without_pool(
2003:         batch_size, in_row_dim, in_col_dim, in_channels,
2004:         out_channels, out_row_dim, out_col_dim,
2005:         stride, input_dilation, kernel_dilation, padding, kernel_dim,
2006:         in_stride, weight_stride, out_stride,
2007:         wrot180, trans_output_1203, trans_input_3120,
2008:         trans_weight_1203, trans_weight_0132,
2009:         input, weights, bias, output,
2010:         act, scale);
2011:     return;
2012:   }
2013: 
2014:   const bool no_bias = bias == NULL;
2015:   const int pool_out_row_dim = (out_row_dim + 2 * pool_padding - pool_size) / pool_stride + 1;
2016:   const int pool_out_col_dim = (out_col_dim + 2 * pool_padding - pool_size) / pool_stride + 1;
2017: 
2018:   for (int b = 0; b < batch_size; b++) {
2019:     for (int porow = 0; porow < pool_out_row_dim; porow++) {
2020:       for (int pocol = 0; pocol < pool_out_col_dim; pocol++) {
2021:         for (int poch = 0; poch < out_channels; poch++) {
2022: 
2023:           elem_t running_max = 0;
2024:           bool running_max_initialized = false;
2025: 
2026:           for (int pwrow = 0; pwrow < pool_size; pwrow++) {
2027:             const int orow = porow * pool_stride + pwrow - pool_padding;
2028: 
2029:             for (int pwcol = 0; pwcol < pool_size; pwcol++) {
2030:               const int ocol = pocol * pool_stride + pwcol - pool_padding;
2031: 
2032:               if (orow < 0 || orow >= out_row_dim || ocol < 0 || ocol >= out_col_dim) {
2033:                 if (!running_max_initialized || running_max < 0) {
2034:                   running_max = 0;
2035:                   running_max_initialized = true;
2036:                 }
2037:               } else {
2038: 
2039:                 acc_t opixel = no_bias ? 0 : bias[poch];
2040: 
2041:                 for (int krow = 0; krow < kernel_dim; krow++) {
2042:                   if ((orow * stride + krow * kernel_dilation - padding) % input_dilation != 0)
2043:                     continue;
2044: 
2045:                   const int irow = (orow * stride + krow * kernel_dilation - padding) / input_dilation;
2046: 
2047:                   for (int kcol = 0; kcol < kernel_dim; kcol++) {
2048:                     if ((ocol * stride + kcol * kernel_dilation - padding) % input_dilation != 0)
2049:                       continue;
2050: 
2051:                     const int icol = (ocol * stride + kcol * kernel_dilation - padding) / input_dilation;
2052: 
2053:                     for (int kch = 0; kch < in_channels; kch++) {
2054:                       const elem_t * in = input + (b * in_row_dim * in_col_dim + irow * in_col_dim + icol) * in_stride + kch;
2055:                       if (trans_input_3120) {
2056:                         // NHWC to CHWN
2057:                         in = input + (kch * in_row_dim * in_col_dim + irow * in_col_dim + icol) * batch_size + b;
2058:                       }
2059: 
2060:                       elem_t ipixel = irow < 0 || irow >= in_row_dim || icol < 0 || icol >= in_col_dim ?
2061:                           0 : *in;
2062: 
2063:                       const int krow_ = wrot180 ? kernel_dim - krow - 1 : krow;
2064:                       const int kcol_ = wrot180 ? kernel_dim - kcol - 1 : kcol;
2065: 
2066:                       elem_t weight = *(weights + (krow_ * kernel_dim * in_channels + kcol_ * in_channels + kch) * weight_stride + poch);
2067:                       if (trans_weight_1203) {
2068:                         // HWIO to WIHO
2069:                         weight = *(weights + (kch * kernel_dim * kernel_dim  + krow_ * kernel_dim + kcol_) * out_channels + poch);
2070:                       } else if (trans_weight_0132) {
2071:                         // HWIO to HWOI
2072:                         weight = *(weights + (krow_ * kernel_dim * out_channels + kcol_ * out_channels + poch) * in_channels + kch);
2073:                       }
2074: 
2075:                       opixel += weight * ipixel;
2076:                     }
2077:                   }
2078:                 }
2079: 
2080:                 opixel = scale_and_sat(opixel, act, scale, 0);
2081:                 if (!running_max_initialized || opixel > running_max) {
2082:                   running_max = opixel;
2083:                   running_max_initialized = true;
2084:                 }
2085:               }
2086: 
2087:               if (pwrow == pool_size - 1 && pwcol == pool_size - 1) {
2088:                 elem_t * out = output + (b * pool_out_row_dim * pool_out_col_dim + porow * pool_out_col_dim + pocol) * out_stride + poch;
2089:                 if (trans_output_1203) {
2090:                   // NHWC to HWNC
2091:                   out = output + (porow * pool_out_col_dim * batch_size + pocol * batch_size + b) * out_channels + poch;
2092:                 }
2093: 
2094:                 *out = running_max;
2095:               }
2096:             }
2097:           }
2098:         }
2099:       }
2100:     }
2101:   }
2102: }
