2105: static void conv_dw_cpu(
2106:         int batch_size, int in_row_dim, int in_col_dim,
2107:         int channels, int out_row_dim, int out_col_dim,
2108:         int stride, int padding, int kernel_dim,
2109: 
2110:         const elem_t * input,
2111:         const elem_t * weights,
2112:         const acc_t * bias,
2113:         elem_t * output,
2114: 
2115:         int act, acc_scale_t scale,
2116:         int pool_size, int pool_stride, int pool_padding) {
2117: 
2118:   const bool no_pool = pool_stride == 0;
2119:   if (no_pool) {
2120:     conv_dw_cpu_without_pool(
2121:         batch_size, in_row_dim, in_col_dim,
2122:         channels, out_row_dim, out_col_dim,
2123:         stride, padding, kernel_dim,
2124:         input, weights, bias, output,
2125:         act, scale);
2126:     return;
2127:   }
2128: 
2129:   const bool no_bias = bias == NULL;
2130:   const int pool_out_row_dim = (out_row_dim + 2 * pool_padding - pool_size) / pool_stride + 1;
2131:   const int pool_out_col_dim = (out_col_dim + 2 * pool_padding - pool_size) / pool_stride + 1;
2132: 
2133:   for (int b = 0; b < batch_size; b++) {
2134:     for (int porow = 0; porow < pool_out_row_dim; porow++) {
2135:       for (int pocol = 0; pocol < pool_out_col_dim; pocol++) {
2136:         for (int ch = 0; ch < channels; ch++) {
2137: 
2138:           elem_t running_max = 0;
2139:           bool running_max_initialized = false;
2140: 
2141:           for (int pwrow = 0; pwrow < pool_size; pwrow++) {
2142:             const int orow = porow * pool_stride + pwrow - pool_padding;
2143: 
2144:             for (int pwcol = 0; pwcol < pool_size; pwcol++) {
2145:               const int ocol = pocol * pool_stride + pwcol - pool_padding;
2146: 
2147:               if (orow < 0 || orow >= out_row_dim || ocol < 0 || ocol >= out_col_dim) {
2148:                 if (!running_max_initialized || running_max < 0) {
2149:                   running_max = 0;
2150:                   running_max_initialized = true;
2151:                 }
2152:               } else {
2153: 
2154:                 acc_t opixel = no_bias ? 0 : bias[ch];
2155: 
2156:                 for (int krow = 0; krow < kernel_dim; krow++) {
2157:                   const int irow = orow * stride + krow - padding;
2158: 
2159:                   for (int kcol = 0; kcol < kernel_dim; kcol++) {
2160:                     const int icol = ocol * stride + kcol - padding;
2161: 
2162:                     const elem_t * in = input + (b * in_row_dim * in_col_dim + irow * in_col_dim + icol) * channels + ch;
2163: 
2164:                     elem_t ipixel = irow < 0 || irow >= in_row_dim || icol < 0 || icol >= in_col_dim ?
2165:                         0 : *in;
2166: 
2167:                     const elem_t weight = *(weights + (ch * kernel_dim + krow) * kernel_dim  + kcol);
2168: 
2169:                     opixel += weight * ipixel;
2170:                   }
2171:                 }
2172: 
2173:                 opixel = scale_and_sat(opixel, act, scale, 0);
2174:                 if (!running_max_initialized || opixel > running_max) {
2175:                   running_max = opixel;
2176:                   running_max_initialized = true;
2177:                 }
2178:               }
2179: 
2180:               if (pwrow == pool_size - 1 && pwcol == pool_size - 1) {
2181:                 elem_t * out = output + (b * pool_out_row_dim * pool_out_col_dim + porow * pool_out_col_dim + pocol) * channels + ch;
2182: 
2183:                 *out = running_max;
2184:               }
2185:             }
2186:           }
2187:         }
2188:       }
2189:     }
2190:   }
2191: }
