2194: static void tiled_conv(
2195:         int batch_size,
2196:         int in_row_dim, int in_col_dim, int in_channels,
2197:         int out_channels, int out_row_dim, int out_col_dim,
2198:         int stride, int input_dilation, int kernel_dilation, int padding, int kernel_dim,
2199:         int in_stride, int weight_stride, int out_stride,
2200:         bool wrot180, bool trans_output_1203, bool trans_input_3120,
2201:         bool trans_weight_1203, bool trans_weight_0132,
2202: 
2203:         int batches,
2204:         int porows, int pocols, int pochs,
2205:         int krows, int kcols, int kchs,
2206: 
2207:         const elem_t * input,
2208:         const elem_t * weights,
2209:         const acc_t * bias,
2210:         elem_t * output,
2211: 
2212:         int act, acc_scale_t scale,
2213:         int pool_size, int pool_stride, int pool_padding,
2214: 
2215:         enum tiled_matmul_type_t tiled_conv_type) {
2216: 
2217: #ifdef GEMMINI_ASSERTIONS
2218:   if (trans_weight_1203 && trans_weight_0132) {
2219:     printf("Only one weight transformation can be applied at a time\n");
2220:     exit(1);
2221:   }
2222: #endif
2223: 
2224:     if (tiled_conv_type == CPU) {
2225:       if (pool_size == 1 && pool_stride == 1 && pool_padding == 0) {
2226:         pool_stride = 0;
2227:       }
2228: 
2229:       // assume in_dim_rows = in_dim_cols
2230:       // and out_dim_rows = out_dim_cols for now
2231:       conv_cpu(
2232:         batch_size, in_row_dim, in_col_dim, in_channels,
2233:         out_channels, out_row_dim, out_col_dim,
2234:         stride, input_dilation, kernel_dilation, padding, kernel_dim,
2235:         in_stride, weight_stride, out_stride,
2236:         wrot180, trans_output_1203, trans_input_3120,
2237:         trans_weight_1203, trans_weight_0132,
2238:         input, weights, bias, output,
2239:         act, scale,
2240:         pool_size, pool_stride, pool_padding);
2241:       return;
2242:     } else if (tiled_conv_type == OS) {
2243:       printf("Gemmini convs do not currently support OS\n");
2244:       exit(1);
2245:     }
2246: 
2247:     // TODO move everything below this into a tiled_conv_outer function to match the tiled_matmul function
2248: 
2249:     bool no_bias = false;
2250:     if (bias == NULL) {
2251:         bias = (acc_t*)1;
2252:         no_bias = true;
2253:     }
2254: 
2255:     bool no_pool = pool_stride == 0;
2256:     if (no_pool) {
2257:         pool_size = 1;
2258:         pool_stride = 1;
2259:         pool_padding = 0;
2260:     }
2261: 
2262:     const bool downsample = stride == 2 && kernel_dim == 1 && in_row_dim % 2 == 0 && in_col_dim % 2 == 0
2263:       && padding == 0 && no_pool && input_dilation == 1 && !trans_input_3120;
2264: 
2265:     const int input_dilated = input_dilation == 2;
2266: 
2267: #ifdef GEMMINI_ASSERTIONS
2268:     {
2269:         // const int orows = porows * pool_stride + pool_size - 1;
2270:         // const int ocols = pocols * pool_stride + pool_size - 1;
2271: 
2272:         // Check that data will fit in scratchpad
2273:         const int spad_rows = tiled_conv_total_spad_rows(false,
2274:             stride, input_dilation, kernel_dilation, downsample, trans_weight_0132, trans_input_3120,
2275:             batches, porows, pocols, pochs, krows, kcols, kchs, pool_size, pool_stride);
2276:         const int acc_rows = tiled_conv_total_spad_rows(true,
2277:             stride, input_dilation, kernel_dilation, downsample, trans_weight_0132, trans_input_3120,
2278:             batches, porows, pocols, pochs, krows, kcols, kchs, pool_size, pool_stride);
2279: 
2280:         if (spad_rows > BANK_NUM * BANK_ROWS / 2) {
2281:             printf("not enough scratchpad space to store inputs and weights, %d\n", spad_rows);
2282:             exit(1);
2283:         }
2284:         if (acc_rows > ACC_ROWS / 2) {
2285:             printf("not enough accumulator space to store outputs\n");
2286:             exit(1);
2287:         }
2288:         if (kernel_dim <= padding) {
2289:             printf("kernel_dim must be larger than padding\n");
2290:             exit(1);
2291:         }
2292:         if (input_dilation > 2) {
2293:             printf("input_dilation > 2 is only supported on CPU\n");
2294:             exit(1);
2295:         }
2296:         if (input_dilation > 1 && stride > 1) {
2297:             printf("input input_dilation is only supported when stride == 1\n");
2298:             exit(1);
2299:         }
2300:         if (trans_output_1203 && !no_pool) {
2301:             printf("Output can only be transposed when pooling is disabled\n");
2302:             exit(1);
2303:         }
2304:         if (trans_input_3120 && trans_weight_0132) {
2305:             printf("Cannot transpose innermost dimensions of both inputs and weights on WS.\n");
2306:             exit(1);
2307:         }
2308:     }
2309: #endif
2310: 
2311:     const size_t st_dram_stride = trans_output_1203 ?
2312:         batch_size * out_channels * sizeof(elem_t) :
2313:         out_stride * sizeof(elem_t);
2314:     gemmini_extended_config_st(st_dram_stride, act, scale);
2315: 
2316:     gemmini_extended3_config_ex(WEIGHT_STATIONARY, 0, 0, 0, input_dilation, stride >> downsample, trans_input_3120, trans_weight_0132, false);
2317: 
2318:     const int pool_out_row_dim = (out_row_dim + 2 * pool_padding - pool_size) / pool_stride + 1;
2319:     const int pool_out_col_dim = (out_col_dim + 2 * pool_padding - pool_size) / pool_stride + 1;
2320:     const int dilated_in_row_dim = in_row_dim + (input_dilation - 1) * (in_row_dim- 1);
2321:     const int dilated_in_col_dim = in_col_dim + (input_dilation - 1) * (in_col_dim- 1);
2322: 
2323:     size_t a_spad_id = 0;
2324:     size_t b_spad_id = 0;
2325: 
2326:     int porow_end = pool_out_row_dim;
2327: 	int porow_start = 0;
2328:     bool a_reuse = false;
2329:     bool b_reuse = false;
2330:     size_t num_kch = ceil_divide_int(in_channels, kchs);
2331:     size_t num_poch = ceil_divide_int(out_channels, pochs);
2332:     size_t num_b = ceil_divide_int(batch_size, batches);
2333:     size_t num_porow = ceil_divide_int((porow_end - porow_start), porows);
2334:     size_t num_pocol = ceil_divide_int(pool_out_col_dim, pocols);
2335:     size_t num_krow = ceil_divide_int(kernel_dim, krows);
2336:     size_t num_kcol = ceil_divide_int(kernel_dim, kcols);
2337: 
2338: 
