2481: static void tiled_conv_dw(
2482:     int batch_size, int in_row_dim, int in_col_dim,
2483:     int channels, int out_row_dim, int out_col_dim,
2484:     int stride, int padding, int kernel_dim,
2485: 
2486:     int batches,
2487:     int porows, int pocols,
2488:     int krows, int kcols,
2489: 
2490:     const elem_t * input,
2491:     const elem_t * weights,
2492:     const acc_t * bias,
2493:     elem_t * output,
2494: 
2495:     int act, acc_scale_t scale,
2496:     int pool_size, int pool_stride, int pool_padding,
2497: 
2498:     enum tiled_matmul_type_t tiled_conv_type) {
2499: 
2500:     if (tiled_conv_type == CPU) {
2501:       if (pool_size == 1 && pool_stride == 1 && pool_padding == 0) {
2502:         pool_stride = 0;
2503:       }
2504: 
2505:       conv_dw_cpu(
2506:         batch_size, in_row_dim, in_col_dim,
2507:         channels, out_row_dim, out_col_dim,
2508:         stride, padding, kernel_dim,
2509:         input, weights, bias, output,
2510:         act, scale,
2511:         pool_size, pool_stride, pool_padding);
2512:       return;
2513:     } else if (tiled_conv_type == OS) {
2514:       printf("Gemmini convs do not currently support OS\n");
2515:       exit(1);
2516:     }
2517: 
2518:     // TODO move everything below this into a tiled_conv_outer function to match the tiled_matmul function
2519: 
2520:     bool no_bias = false;
2521:     if (bias == NULL) {
2522:         bias = (acc_t*)1;
2523:         no_bias = true;
2524:     }
2525: 
2526:     bool no_pool = pool_stride == 0;
2527:     if (no_pool) {
2528:         pool_size = 1;
2529:         pool_stride = 1;
2530:         pool_padding = 0;
2531:     }
2532: 
2533: #ifdef GEMMINI_ASSERTIONS
2534:     {
2535:         // const int orows = porows * pool_stride + pool_size - 1;
2536:         // const int ocols = pocols * pool_stride + pool_size - 1;
2537: 
2538:         // Check that data will fit in scratchpad
2539:         const int spad_rows = tiled_conv_total_spad_rows(false,
2540:             stride, 1, 1, false, false, false,
2541:             batches, porows, pocols, 1, krows, kcols, 1, pool_size, pool_stride);
2542:         const int acc_rows = tiled_conv_total_spad_rows(true,
2543:             stride, 1, 1, false, false, false,
2544:             batches, porows, pocols, 1, krows, kcols, 1, pool_size, pool_stride);
2545: 
2546:         if (spad_rows > BANK_NUM * BANK_ROWS / 2) {
2547:             printf("not enough scratchpad space to store inputs and weights, %d\n", spad_rows);
2548:             exit(1);
2549:         }
2550:         if (acc_rows > ACC_ROWS / 2) {
2551:             printf("not enough accumulator space to store outputs\n");
2552:             exit(1);
2553:         }
2554:         if (kernel_dim <= padding) {
2555:             printf("kernel_dim must be larger than padding\n");
2556:             exit(1);
2557:         }
2558:     }
2559: #endif
2560: 
2561:     const size_t st_dram_stride = channels * sizeof(elem_t);
2562:     gemmini_extended_config_st(st_dram_stride, act, scale);
2563: 
2564:     gemmini_extended3_config_ex(WEIGHT_STATIONARY, 0, 0, 0, 1, stride, false, false, false);
2565: 
2566:     const int pool_out_row_dim = (out_row_dim + 2 * pool_padding - pool_size) / pool_stride + 1;
2567:     const int pool_out_col_dim = (out_col_dim + 2 * pool_padding - pool_size) / pool_stride + 1;
2568: 
2569:     for (int b = 0; b < batch_size; b += batches) {
2570:         for (int porow = 0; porow < pool_out_row_dim; porow += porows) {
2571:             const int orow = porow * pool_stride - pool_padding;
2572: 
2573:             for (int pocol = 0; pocol < pool_out_col_dim; pocol += pocols) {
2574:                 const int ocol = pocol * pool_stride - pool_padding;
2575: 
2576:                 for (int ch = 0; ch < channels; ch++) {
2577:                     for (int krow = 0; krow < kernel_dim; krow += krows) {
2578:                         const int orow_floored = orow < 0 ? 0 : orow;
2579:                         int irow = orow_floored * stride + krow - padding;
2580: 
2581:                         for (int kcol = 0; kcol < kernel_dim; kcol += kcols) {
2582:                             const int ocol_floored = ocol < 0 ? 0 : ocol;
2583:                             int icol = ocol_floored * stride + kcol - padding;
2584: 
2585:                             elem_t * out = output + (b * pool_out_row_dim * pool_out_col_dim + porow * pool_out_col_dim + pocol) * channels + ch;
2586: 
2587:                             if (krow + krows < kernel_dim ||
2588:                                     kcol + kcols < kernel_dim) {
2589:                                 out = NULL;
2590:                             }
2591: 
2592:                             const acc_t * bias_ = bias + ch;
2593:                             if (krow > 0 ||
2594:                                     kcol > 0) {
2595:                                 bias_ = NULL;
2596:                             }
2597: 
2598:                             const int batches_ = batch_size - b > batches ? batches : batch_size - b;
2599:                             const int porows_ = pool_out_row_dim - porow > porows ? porows : pool_out_row_dim - porow;
2600:                             const int pocols_ = pool_out_col_dim - pocol > pocols ? pocols : pool_out_col_dim - pocol;
2601:                             const int krows_ = kernel_dim - krow > krows ? krows : kernel_dim - krow;
2602:                             const int kcols_ = kernel_dim - kcol > kcols ? kcols : kernel_dim - kcol;
2603: 
2604:                             const int ocols_ = pocols_ * pool_stride + pool_size - 1;
2605:                             const int orows_ = porows_ * pool_stride + pool_size - 1;
2606: 
2607:                             const int plpad = ocol < 0 ? -ocol : 0;
2608:                             const int prpad = ocol + ocols_ > out_col_dim ? ocol + ocols_ - out_col_dim : 0;
2609:                             const int pupad = orow < 0 ? -orow : 0;
2610:                             const int pdpad = orow + orows_ > out_row_dim ? orow + orows_ - out_row_dim : 0;
2611: 
2612:                             const int icols_ = (ocols_ - plpad - prpad) * stride + kcols_ - 1;
2613:                             const int irows_ = (orows_ - pupad - pdpad) * stride + krows_ - 1;
2614: 
2615:                             int lpad = icol < 0 ? -icol : 0;
2616:                             int rpad = icol + icols_ > in_col_dim ? icol + icols_ - in_col_dim : 0;
2617:                             int upad = irow < 0 ? -irow : 0;
2618:                             int dpad = irow + irows_ > in_row_dim ? irow + irows_ - in_row_dim : 0;
2619: 
2620:                             const elem_t * weights_slice = weights + (ch*kernel_dim + krow) * kernel_dim + kcol;
2621: 
2622:                             const elem_t *in = input + (b * in_row_dim * in_col_dim + (irow+upad) * in_col_dim + (icol+lpad)) * channels + ch;
2623: 
2624:                             sp_tiled_conv(
2625:                                 batch_size, in_row_dim, in_col_dim, channels,
2626:                                 channels, out_row_dim, out_col_dim,
2627:                                 pool_out_row_dim, pool_out_col_dim,
2628: 
2629:                                 stride, padding, kernel_dim, 1,
2630:                                 channels, 1, channels,
2631: 
2632:                                 pool_size, pool_stride, pool_padding,
2633: 
2634:                                 batches_,
2635:                                 porows_, pocols_, 1,
2636:                                 krows_, kcols_, 1,
2637: 
2638:                                 lpad, rpad, upad, dpad,
2639:                                 plpad, prpad, pupad, pdpad,
2640: 
2641:                                 in,
2642:                                 weights_slice,
2643:                                 out,
2644:                                 bias_,
2645: 
2646:                                 act, scale,
2647: 
2648:                                 false, false, false,
2649:                                 false, false,
2650: 
2651:                                 no_bias, no_pool, false, false,
2652:                                 true, 0, 0);
2653: 
2654:                         }
2655:                     }
2656:                 }
2657:             }
2658:         }
2659:     }
2660: }
