2662: // need to specify each operand/output's stride
2663: // stride only for trans == false, wrot == false
2664: static void tiled_conv_stride_auto(
2665:         int batch_size, int in_row_dim, int in_col_dim, int in_channels,
2666:         int out_channels, int out_row_dim, int out_col_dim,
2667:         int stride, int input_dilation, int kernel_dilation, int padding, int kernel_dim,
2668:         int in_stride, int weight_stride, int out_stride, // specify in/output's stride
2669:         bool wrot180, bool trans_output_1203, bool trans_input_3120,
2670:         bool trans_weight_1203, bool trans_weight_0132,
2671: 
2672:         const elem_t * input,
2673:         const elem_t * weights,
2674:         const acc_t * bias,
2675:         elem_t * output,
2676: 
2677:         int act, acc_scale_t scale,
2678:         int pool_size, int pool_stride, int pool_padding,
2679: 
2680:         enum tiled_matmul_type_t tiled_conv_type) {
2681: 
2682:     const bool no_pool = pool_stride == 0;
2683:     if (no_pool) {
2684:         pool_size = 1;
2685:         pool_stride = 1;
2686:         pool_padding = 0;
2687:     }
2688: 
2689:     const int pool_out_row_dim = (out_row_dim + 2 * pool_padding - pool_size) / pool_stride + 1;
2690:     const int pool_out_col_dim = (out_col_dim + 2 * pool_padding - pool_size) / pool_stride + 1;
2691: 
2692:     const bool downsample = stride == 2 && kernel_dim == 1 && padding == 0 && no_pool && in_row_dim % 2 == 0 && in_col_dim % 2 == 0;
2693: 
2694:     // Tile convolution params
2695: 
2696:     // int args[] = {batch_size, porows, pocols, pochs, krows, kcols, kchs};
2697:     int args[] = {batch_size, pool_out_row_dim, pool_out_col_dim, out_channels, kernel_dim, kernel_dim, in_channels};
2698:     const int max_args[] = {batch_size, pool_out_row_dim, pool_out_col_dim, out_channels, kernel_dim, kernel_dim, in_channels};
2699: 
2700:     const int orows_idx = 1;
2701:     const int ocols_idx = 2;
2702:     const int out_channels_idx = 3;
2703:     const int in_channels_idx = 6;
2704: 
2705:     // We divide by 2 for the sake of double-buffering
2706:     const int max_spad_rows = (BANK_NUM*BANK_ROWS / 2);
2707:     const int max_acc_rows = (ACC_ROWS / 2);
2708: 
2709:     int spad_rows = tiled_conv_total_spad_rows(false,
2710:         stride, input_dilation, kernel_dilation, downsample, trans_weight_0132, trans_input_3120,
2711:         args[0], args[1], args[2], args[3], args[4], args[5], args[6], pool_size, pool_stride);
2712:     int acc_rows = tiled_conv_total_spad_rows(true,
2713:         stride, input_dilation, kernel_dilation, downsample, trans_weight_0132, trans_input_3120,
2714:         args[0], args[1], args[2], args[3], args[4], args[5], args[6], pool_size, pool_stride);
2715: 
2716:     while (spad_rows > max_spad_rows || acc_rows > max_acc_rows) {
2717:         int max_val = -1;
2718:         int max_idx = -1;
2719: 
2720:         for (size_t i = 0; i < sizeof(args)/sizeof(args[0]); i++) {
2721:             // We avoid reducing ocols when possible to keep the spatial array fully utilized
2722:             if (!(i == ocols_idx && args[i] <= DIM && args[orows_idx] > 1)
2723:                     && args[i] > max_val) {
2724:                 max_val = args[i];
2725:                 max_idx = i;
2726:             }
2727:         }
2728: 
2729:         if (max_idx == out_channels_idx || max_idx == in_channels_idx) {
2730:             // For input and output channels, there's no point in subtracting by just one
2731:             if (args[max_idx] % DIM != 0) {
2732:                 args[max_idx] = (args[max_idx] / DIM) * DIM;
2733:             } else {
2734:                 args[max_idx] -= DIM;
2735:             }
2736:             args[max_idx] = args[max_idx] == 0 ? 1 : args[max_idx];
2737:         } else {
2738:             args[max_idx]--;
2739:         }
2740: 
2741:         spad_rows = tiled_conv_total_spad_rows(false,
2742:             stride, input_dilation, kernel_dilation, downsample, trans_weight_0132, trans_input_3120,
2743:             args[0], args[1], args[2], args[3], args[4], args[5], args[6], pool_size, pool_stride);
2744:         acc_rows = tiled_conv_total_spad_rows(true,
2745:             stride, input_dilation, kernel_dilation, downsample, trans_weight_0132, trans_input_3120,
2746:             args[0], args[1], args[2], args[3], args[4], args[5], args[6], pool_size, pool_stride);
2747:     }
2748: 
2749:     // Check if we can increase ocols
2750:     bool not_increased = false;
2751:     while (!not_increased) {
2752:         not_increased = true;
2753: 
2754:         int args_candidate[] = {args[0], args[1], args[2], args[3], args[4], args[5], args[6]};
2755:         args_candidate[ocols_idx]++;
2756: 
2757:         if (args_candidate[ocols_idx] > max_args[ocols_idx])
2758:             continue;
2759: 
2760:         spad_rows = tiled_conv_total_spad_rows(false,
2761:             stride, input_dilation, kernel_dilation, downsample, trans_weight_0132, trans_input_3120,
2762:             args_candidate[0], args_candidate[1], args_candidate[2], args_candidate[3], args_candidate[4], args_candidate[5], args_candidate[6], pool_size, pool_stride);
2763:         acc_rows = tiled_conv_total_spad_rows(true,
2764:             stride, input_dilation, kernel_dilation, downsample, trans_weight_0132, trans_input_3120,
2765:             args_candidate[0], args_candidate[1], args_candidate[2], args_candidate[3], args_candidate[4], args_candidate[5], args_candidate[6], pool_size, pool_stride);
2766: 
2767:         if (spad_rows <= max_spad_rows && acc_rows <= max_acc_rows) {
2768:             args[ocols_idx] = args_candidate[ocols_idx];
2769:             not_increased = false;
2770:         }
2771:     }
2772: 
2773:     // Check if there are any parameters that we can currently still increase
2774:     bool nothing_increased = false;
2775:     while (!nothing_increased) {
2776:         nothing_increased = true;
2777: 
2778:         for (size_t i = 0; i < sizeof(args)/sizeof(args[0]); i++) {
2779:             int args_candidate[] = {args[0], args[1], args[2], args[3], args[4], args[5], args[6]};
2780:             args_candidate[i]++;
2781: 
2782:             if (args_candidate[i] > max_args[i])
2783:                 continue;
