2787:                 args_candidate[0], args_candidate[1], args_candidate[2], args_candidate[3], args_candidate[4], args_candidate[5], args_candidate[6], pool_size, pool_stride);
2788:             acc_rows = tiled_conv_total_spad_rows(true,
