2790:                 args_candidate[0], args_candidate[1], args_candidate[2], args_candidate[3], args_candidate[4], args_candidate[5], args_candidate[6], pool_size, pool_stride);
2791: 
2792:             if (spad_rows <= max_spad_rows && acc_rows <= max_acc_rows) {
2793:                 args[i] = args_candidate[i];
2794:                 nothing_increased = false;
2795:             }
2796:         }
2797:     }
2798: 
