2895: // This function is for a convolution with kernel_dim=1, stride==2, padding=0, and no pooling
2896: static void tiled_conv_downsample(
2897:         int batch_size, int in_row_dim, int in_col_dim, int in_channels,
2898:         int out_channels, int out_row_dim, int out_col_dim,
2899:         int in_stride, int weight_stride, int out_stride,
2900: 
2901:         const elem_t * input,
2902:         const elem_t * weights,
2903:         const acc_t * bias,
2904:         elem_t * output,
2905: 
2906:         int act, acc_scale_t scale,
2907: 
2908:         enum tiled_matmul_type_t tiled_conv_type) {
2909: 
2910:     // Rectangular dimensions for this function are currently not supported
2911:     if (in_row_dim != in_col_dim || out_row_dim != out_col_dim) {
2912:         printf("Rectangular convolutions for tiled_conv_downsample are currently not supported.\n");
2913:         exit(1);
2914:     }
2915: 
2916:     const int in_dim = in_row_dim;
2917:     const int out_dim = out_row_dim;
2918: 
2919:     const int stride = 2;
2920: 
2921:     for (int b = 0; b < batch_size; b++) {
2922:         for (int irow = 0; irow < in_row_dim; irow += stride) {
2923:             const int orow = irow / stride;
2924: 
2925:             const int I = in_col_dim / stride; // number of columns in row
2926:             const int J = out_channels;
2927:             const int K = in_channels;
2928: 
2929:             const elem_t * A = input + (b * in_dim + irow) * in_dim * in_stride;
2930:             const elem_t * B = weights;
2931:             const acc_t * D = bias;
2932:             elem_t * C = output + (b * out_dim + orow) * out_dim * out_stride;
2933: 
2934:             const int A_stride = in_stride * 2;
2935:             const int B_stride = weight_stride;
2936:             const int D_stride = out_stride;
2937:             const int C_stride = out_stride;
2938: 
2939:             tiled_matmul_auto(I, J, K, A, B, (void*)D, (void*)C,
2940:                     A_stride, B_stride, D_stride, C_stride,
2941:                     MVIN_SCALE_IDENTITY, MVIN_SCALE_IDENTITY,
2942:                     MVIN_SCALE_IDENTITY, act, scale, 0,
2943:                     true, false, false, false, false, 0, tiled_conv_type);
2944:         }
2945:     }
2946: }
