2994: 
2995:     while (spad_rows > max_spad_rows || acc_rows > max_acc_rows) {
2996:         int max_val = -1;
2997:         int max_idx = -1;
2998: 
2999:         for (size_t i = 0; i < sizeof(args)/sizeof(args[0]); i++) {
3000:             // We avoid reducing ocols when possible to keep the spatial array fully utilized
3001:             if (!(i == ocols_idx && args[i] <= DIM && args[orows_idx] > 1)
3002:                     && args[i] > max_val) {
3003:                 max_val = args[i];
3004:                 max_idx = i;
3005:             }
3006:         }
3007: 
3008:         if (max_idx == out_channels_idx) {
3009:             // For input and output channels, there's no point in subtracting by just one
3010:             if (args[max_idx] % DIM != 0) {
3011:                 args[max_idx] = (args[max_idx] / DIM) * DIM;
3012:             } else {
3013:                 args[max_idx] -= DIM;
3014:             }
3015:             args[max_idx] = args[max_idx] == 0 ? 1 : args[max_idx];
3016:         } else {
3017:             args[max_idx]--;
3018:         }
3019: 
3020:         spad_rows = tiled_conv_total_spad_rows(false,
3021:             stride, 1, 1, false, false, false,
3022:             args[0], args[1], args[2], args[3], args[4], args[5], args[6], pool_size, pool_stride);
3023:         acc_rows = tiled_conv_total_spad_rows(true,
3024:             stride, 1, 1, false, false, false,
3025:             args[0], args[1], args[2], args[3], args[4], args[5], args[6], pool_size, pool_stride);
3026:     }
3027: 
3028:     // Check if we can increase ocols
3029:     bool not_increased = false;
3030:     while (!not_increased) {
3031:         not_increased = true;
3032: 
3033:         int args_candidate[] = {args[0], args[1], args[2], args[3], args[4], args[5], args[6]};
3034:         args_candidate[ocols_idx]++;
3035: 
3036:         if (args_candidate[ocols_idx] > max_args[ocols_idx])
3037:             continue;
3038: 
3039:         spad_rows = tiled_conv_total_spad_rows(false,
3040:             stride, 1, 1, false, false, false,
3041:             args_candidate[0], args_candidate[1], args_candidate[2], args_candidate[3], args_candidate[4], args_candidate[5], args_candidate[6], pool_size, pool_stride);
3042:         acc_rows = tiled_conv_total_spad_rows(true,
3043:             stride, 1, 1, false, false, false,
