3045: 
3046:         if (spad_rows <= max_spad_rows && acc_rows <= max_acc_rows) {
3047:             args[ocols_idx] = args_candidate[ocols_idx];
3048:             not_increased = false;
3049:         }
3050:     }
3051: 
3052:     // Check if there are any parameters that we can currently still increase
3053:     bool nothing_increased = false;
3054:     while (!nothing_increased) {
3055:         nothing_increased = true;
3056: 
3057:         for (size_t i = 0; i < sizeof(args)/sizeof(args[0]); i++) {
3058:             int args_candidate[] = {args[0], args[1], args[2], args[3], args[4], args[5], args[6]};
3059:             args_candidate[i]++;
3060: 
3061:             if (args_candidate[i] > max_args[i])
3062:                 continue;
3063: 
3064:             spad_rows = tiled_conv_total_spad_rows(false,
3065:                 stride, 1, 1, false, false, false,
3066:                 args_candidate[0], args_candidate[1], args_candidate[2], args_candidate[3], args_candidate[4], args_candidate[5], args_candidate[6], pool_size, pool_stride);
3067:             acc_rows = tiled_conv_total_spad_rows(true,
3068:                 stride, 1, 1, false, false, false,
3069:                 args_candidate[0], args_candidate[1], args_candidate[2], args_candidate[3], args_candidate[4], args_candidate[5], args_candidate[6], pool_size, pool_stride);
3070: 
3071:             if (spad_rows <= max_spad_rows && acc_rows <= max_acc_rows) {
3072:                 args[i] = args_candidate[i];
3073:                 nothing_increased = false;
3074:             }
3075:         }
3076:     }
3077: 
3078:     const int batches = args[0];
3079:     const int orows = args[1];
3080:     const int ocols = args[2];
3081:     const int ochs = 1; // args[3];
3082:     const int krows = args[4];
3083:     const int kcols = args[5];
3084:     const int kchs = 1; // args[6];
3085: 
3086:     /*
3087:     spad_rows = tiled_conv_total_spad_rows(false,
3088:         stride, 1, 1, false, false, false,
3089:         args[0], args[1], args[2], args[3], args[4], args[5], args[6], pool_size, pool_stride);
3090:     acc_rows = tiled_conv_total_spad_rows(true,
