3099:     printf("kcols   = %d\n", kcols);
3100:     printf("kchs    = %d\n\n", kchs);
3101: 
3102:     printf("total spad_rows reserved: %d\n", spad_rows);
3103:     printf("total acc_rows reserved: %d\n\n", acc_rows);
3104: 
3105:     printf("scratchpad row utilization: %d%%\n", (spad_rows*100) / max_spad_rows);
3106:     printf("accumulator row utilization: %d%%\n\n", (acc_rows*100) / max_acc_rows);
3107: 
3108:     printf("inner matmul size: i=%d, j=%d, k=%d\n\n", ocols, ochs, kchs);
3109:     */
3110: 
3111:     tiled_conv_dw(
3112:         batch_size, in_row_dim, in_col_dim,
3113:         channels, out_row_dim, out_col_dim,
3114:         stride, padding, kernel_dim,
3115: 
3116:         batches,
3117:         orows, ocols,
3118:         krows, kcols,
3119: 
3120:         input,
3121:         weights,
