3132: static void resadd_cpu(const size_t I, const size_t J,
3133:         const size_t stride,
3134:         const scale_t A_scale,
3135:         const scale_t B_scale,
3136:         const acc_scale_t C_scale,
3137:         const elem_t * A,
3138:         const elem_t * B,
3139:         elem_t * C,
3140:         bool relu) {
3141: 
3142: 	const int minimum = relu ? 0 : elem_t_min;
3143: 
3144:     for (size_t i = 0; i < I; i++) {
3145:         for (size_t j = 0; j < J; j++) {
3146:             const elem_t * a = A + i * stride + j;
3147:             const elem_t * b = B + i * stride + j;
3148:             elem_t * c = C + i * stride + j;
3149: 
3150:             acc_t result = MVIN_SCALE(*a, A_scale) + MVIN_SCALE(*b, B_scale);
3151:             result = ACC_SCALE(result, C_scale);
3152:             result = result > elem_t_max ? elem_t_max :
3153:                 (result < minimum ? minimum : result);
3154: 
3155:             *c = result;
3156:         }
3157:     }
3158: }
