3227: // Compute MVIN_SCALE(A, A_scale) + MVIN_SCALE(B, B_scale) = C
3228: static void tiled_resadd(const size_t I, const size_t J,
3229:         const size_t stride,
3230:         const size_t tile_I, const size_t tile_J,
3231:         const scale_t A_scale,
3232:         const scale_t B_scale,
3233:         const acc_scale_t C_scale,
3234:         const elem_t * A,
3235:         const elem_t * B,
3236:         elem_t * C,
3237:         bool relu,
3238:         enum tiled_matmul_type_t matadd_type) {
3239: 
3240:     gemmini_extended_config_st(stride * sizeof(elem_t), relu ? RELU : NO_ACTIVATION, C_scale);
3241:     gemmini_config_ex(WS, 0, 0);
3242: 
3243:     gemmini_extended4_config_ld(stride * sizeof(elem_t), A_scale, true, DIM, 0);
3244:     gemmini_extended4_config_ld(stride * sizeof(elem_t), B_scale, true, DIM, 1);
3245: 
3246:     for (size_t i = 0; i < I; i += tile_I) {
3247:         for (size_t j = 0; j < J; j += tile_J) {
3248:             const size_t I_tile = i + tile_I <= I ? tile_I : I - i;
3249:             const size_t J_tile = j + tile_J <= J ? tile_J : J - j;
3250: 
3251:             const elem_t * a = A + i * stride + j;
3252:             const elem_t * b = B + i * stride + j;
3253:             elem_t * c = C + i * stride + j;
3254: 
3255:             sp_tiled_resadd(I_tile, J_tile,
3256:                     A_scale, B_scale, a, b, c,
3257:                     stride, stride, stride,
3258:                     relu);
3259:         }
3260:     }
3261: 
3262:     gemmini_fence();
3263: }
3264: 
3265: // Compute (A >> A_shift) + B = C
3266: // specify stride
3267: static void tiled_resadd_stride_auto(const size_t I, const size_t J,
3268:         const scale_t A_scale,
3269:         const scale_t B_scale,
3270:         const acc_scale_t C_scale,
3271:         const size_t stride,
3272:         const elem_t * A,
3273:         const elem_t * B,
3274:         elem_t * C,
3275:         bool relu,
3276:         enum tiled_matmul_type_t matadd_type) {
3277: 
3278:     if (matadd_type == CPU) {
3279:         resadd_cpu(I, J, stride,
3280:             A_scale, B_scale, C_scale, A, B, C,
3281:             relu);
3282:         return;
3283:     }
3284: 
3285:     size_t tile_I = I, tile_J = J;
3286: 
3287:     // size_t total_spad_rows = 2 * (tile_I / DIM + (tile_I % DIM != 0))*DIM * (tile_J / DIM + (tile_J % DIM != 0));
3288:     size_t total_acc_rows = (tile_I / DIM + (tile_I % DIM != 0))*DIM * (tile_J / DIM + (tile_J % DIM != 0));
3289: 
3290:     // TODO this is a very inefficient way of doing this...
3291:     while (total_acc_rows > ACC_ROWS / 2) {
3292:         //if(tile_J > MAX_BLOCK_LEN * DIM)
3293:         //    tile_J = MAX_BLOCK_LEN * DIM;
3294:         //else
3295:         if (tile_I >= tile_J || tile_J <= DIM)
3296:             tile_I /= 2;
3297:         else
3298:             tile_J -= DIM;
3299: 
3300:         total_acc_rows = (tile_I / DIM + (tile_I % DIM != 0))*DIM * (tile_J / DIM + (tile_J % DIM != 0));
3301:     }
3302: 
3303:     // printf("tile_I: %llu\n", tile_I);
3304:     // printf("tile_J: %llu\n", tile_J);
3305: 
3306:     if (matadd_type == WS) {
3307:       tiled_resadd(I, J, stride, tile_I, tile_J,
3308:             A_scale, B_scale, C_scale, A, B, C,
3309:             relu, matadd_type);
3310:     }
3311:     else {
3312:       printf("Unsupported type\n");
3313:       exit(1);
3314:     }
3315: }
3316: 
3317: _STATIC void tiled_resadd_auto(const size_t I, const size_t J,
3318:         const scale_t A_scale,
3319:         const scale_t B_scale,
3320:         const acc_scale_t C_scale,
3321:         const elem_t * A,
3322:         const elem_t * B,
3323:         elem_t * C,
3324:         bool relu,
3325:         enum tiled_matmul_type_t matadd_type) {
3326:     tiled_resadd_stride_auto(I, J,
3327:         A_scale, B_scale, C_scale,
3328:         J,
3329:         A, B, C,
3330:         relu, matadd_type);
3331: }
