3333: static void global_average_cpu(const elem_t * input, elem_t * output,
3334:     int batches, int channels, int dim) {
3335:   const int count = dim * dim;
3336: 
3337:   for (int batch = 0; batch < batches; batch++) {
3338:     for (int channel = 0; channel < channels; channel++) {
3339:       acc_t sum = 0;
3340:       for (int row = 0; row < dim; row++) {
3341:         for (int col = 0; col < dim; col++) {
3342:           size_t pixel = batch * dim * dim + row * dim + col;
3343: 
3344:           sum += input[pixel * channels + channel];
3345:         }
3346:       }
3347: 
3348: #ifdef ELEM_T_IS_FLOAT
3349:       output[batch * channels + channel] = sum / count;
3350: #else
3351:       output[batch * channels + channel] = (sum + count/2) / count;
3352: #endif
3353:     }
3354:   }
3355: }
3356: 
3357: 
3358: static void sp_tiled_global_average(const elem_t * input, elem_t * output,
3359:     int batches, int channels, int dim, int channel_tile_size) {
3360:   const uint32_t C_acc_addr_start = ((uint32_t)1 << 31);
3361: 
3362:   size_t blocks = channel_tile_size/DIM + (channel_tile_size % DIM != 0);
3363:   if (blocks > MAX_BLOCK_LEN) blocks = MAX_BLOCK_LEN;
3364: 
3365:   for (int channel = 0; channel < channel_tile_size; channel += blocks*DIM) {
3366:     for (int row = 0; row < dim; row++) {
3367:       for (int col = 0; col < dim; col++) {
3368:         const elem_t * in = input +
3369:           (row * dim + col) * channels +
3370:           channel;
3371: 
3372:         const uint32_t acc_addr_start = C_acc_addr_start |
3373:           ((row != 0 || col != 0) << 30);
3374: 
3375:         const uint32_t acc_addr = acc_addr_start + channel / DIM;
3376: 
3377:         const size_t cols = channel + blocks*DIM <= channel_tile_size ?
3378:           blocks*DIM : channel_tile_size - channel;
3379: 
3380:         const size_t rows = 1;
3381: 
3382:         gemmini_extended_mvin(in, acc_addr, cols, rows);
3383:       }
3384:     }
3385:   }
3386: 
3387:   for (int channel = 0; channel < channel_tile_size; channel += DIM) {
3388:     elem_t * out = output + channel;
3389: 
3390:     const uint32_t acc_addr = C_acc_addr_start + channel / DIM;
3391: 
3392:     const size_t cols = channel + DIM <= channel_tile_size ?
3393:       DIM : channel_tile_size - channel;
3394: 
3395:     const size_t rows = 1; // TODO we should move out more than just one row here
3396: 
3397:     gemmini_extended_mvout(out, acc_addr, cols, rows);
3398:   }
3399: }
3400: 
3401: 
3402: static void tiled_global_average(const elem_t * input, elem_t * output,
3403:     int batches, int channels, int dim,
3404:     int channel_tile_size) {
3405: 
3406:   gemmini_extended4_config_ld(DIM*sizeof(elem_t), MVIN_SCALE_IDENTITY, true, 1, 0);
3407:   gemmini_config_ex(0, NO_ACTIVATION, 0);
3408:   gemmini_extended_config_st(0, NO_ACTIVATION, 1.0 / (dim*dim));
3409: 
3410:   for (int batch = 0; batch < batches; batch++) {
3411:     for (int channel = 0; channel < channels; channel += channel_tile_size) {
3412:       const int tile_size = channel + channel_tile_size <= channels ?
3413:         channel_tile_size : channels - channel;
3414: 
3415:       sp_tiled_global_average(input + batch * dim * dim * channels + channel,
3416:           output + batch * channels + channel,
3417:           batches, channels, dim, tile_size);
3418:     }
3419:   }
3420: }
3421: 
3422: 
3423: static void tiled_global_average_auto(const elem_t * input, elem_t * output,
3424:     int batches, int channels, int dim,
3425:     enum tiled_matmul_type_t type) {
3426:   if (type == CPU) {
3427:     return global_average_cpu(input, output, batches, channels, dim);
3428:   }
3429: 
3430:   int channel_tile_size = channels;
3431: 
3432:   int acc_rows = channel_tile_size / DIM + (channel_tile_size % DIM != 0);
3433:   while (acc_rows > ACC_ROWS) {
3434:     channel_tile_size--;
3435:     acc_rows = channel_tile_size / DIM + (channel_tile_size % DIM != 0);
3436:   }
3437: 
3438:   tiled_global_average(input, output, batches, channels, dim,
3439:       channel_tile_size);
3440: }
