3442: static void sp_tiled_norm(const size_t I, const size_t J,
3443:         const acc_t * in, elem_t * out,
3444:         size_t A_row_stride, size_t C_row_stride,
3445:         int act) {
3446: #ifdef HAS_NORMALIZATIONS
3447:     size_t A_blocks = (J/DIM + (J % DIM != 0));
3448:     if (A_blocks > MAX_BLOCK_LEN_ACC) A_blocks = MAX_BLOCK_LEN_ACC;
3449:     size_t C_blocks = (J/DIM + (J % DIM != 0));
3450:     if (C_blocks > MAX_BLOCK_LEN) C_blocks = MAX_BLOCK_LEN;
3451: 
3452:     const uint32_t D_sp_addr_start = 1 << (ADDR_LEN-1);
3453:     const uint32_t C_sp_addr_start = 3 << (ADDR_LEN-2);
3454: 
3455:     const size_t rounded_up_J = (J / DIM + (J % DIM != 0)) * DIM;
3456: 
3457:     for (size_t i = 0; i < I; i += DIM) {
3458:         // Mvin
3459:         for (size_t j = 0; j < J; j += A_blocks * DIM) {
3460:             const size_t cols = j + A_blocks*DIM <= J ? A_blocks*DIM : J-j;
3461:             const size_t rows = i + DIM <= I ? DIM : I-i;
3462: 
3463:             const acc_t * const A_dram_addr = in + i * A_row_stride + j;
3464:             const uint32_t A_sp_addr = D_sp_addr_start + i * (rounded_up_J/DIM) + j;
3465: 
3466:             gemmini_extended_mvin(A_dram_addr, A_sp_addr, cols, rows);
3467:         }
3468: 
3469:         // Mvout
3470:         if (act == LAYERNORM) {
3471:             uint32_t norm_cmds[][2] = {{1,2},{3,4},{0,0}};
3472:             const int norm_cmds_size = sizeof(norm_cmds) / sizeof(norm_cmds[0]);
3473:             const size_t rows = I - i < DIM ? I - i : DIM;
3474:             for (size_t row = 0; row < rows; row += NORM_STAT_IDS) {
3475:                 const size_t stat_ids = rows - row > NORM_STAT_IDS ?
3476:                     NORM_STAT_IDS : rows - row;
3477:                 for (int cmd = 0; cmd < norm_cmds_size; cmd++) {
3478:                     for (size_t stat_id = 0; stat_id < stat_ids; stat_id++) {
3479:                         gemmini_config_norm(0, 0, 0, 0, stat_id, 0, 0);
3480:                         const size_t r = row + stat_id;
3481:                         for (size_t jj = 0; jj < J; jj += C_blocks * DIM) {
3482:                             uint32_t norm_C_sp_addr = C_sp_addr_start + i * (rounded_up_J/DIM) + jj + r;
3483:                             if (jj + C_blocks*DIM >= J) {
3484:                                 norm_C_sp_addr |= (norm_cmds[cmd][1] << 26); // Final mean/inv-std-dev calculation
3485:                             } else {
3486:                                 norm_C_sp_addr |= (norm_cmds[cmd][0] << 26); // Accumulate sum/variance
3487:                             }
3488:                             void * const C_dram_addr = (int8_t*)out +
3489:                                 (i*C_row_stride + jj) * sizeof(elem_t) +
3490:                                 r * C_row_stride * sizeof(elem_t);
3491:                             const size_t cols = J - jj < C_blocks * DIM ? J - jj : C_blocks * DIM;
3492:                             gemmini_extended_mvout(C_dram_addr, norm_C_sp_addr, cols, 1);
3493:                         }
3494:                     }
3495:                 }
3496:             }
3497:         } else if (act == SOFTMAX) {
3498:             uint32_t norm_cmds[][2] = {{5,5},{6,7},{0,0}};
3499:             const int norm_cmds_size = sizeof(norm_cmds) / sizeof(norm_cmds[0]);
3500:             const size_t rows = I - i < DIM ? I - i : DIM;
3501:             for (size_t row = 0; row < rows; row += NORM_STAT_IDS) {
3502:                 const size_t stat_ids = rows - row > NORM_STAT_IDS ?
3503:                     NORM_STAT_IDS : rows - row;
3504:                 for (int cmd = 0; cmd < norm_cmds_size; cmd++) {
3505:                     for (size_t stat_id = 0; stat_id < stat_ids; stat_id++) {
3506:                         // set stat id only
3507:                         gemmini_config_norm(0, 0, 1, 0, stat_id, 0, 0);
3508:                         const size_t r = row + stat_id;
3509:                         for (size_t jj = 0; jj < J; jj += C_blocks * DIM) {
3510:                             uint32_t norm_C_sp_addr = C_sp_addr_start + i * (rounded_up_J/DIM) + jj + r;
3511:                             if (jj + C_blocks*DIM >= J) {
3512:                                 norm_C_sp_addr |= (norm_cmds[cmd][1] << 26); // Final mean/inv-std-dev calculation
3513:                             } else {
3514:                                 norm_C_sp_addr |= (norm_cmds[cmd][0] << 26); // Accumulate sum/variance
3515:                             }
3516:                             void * const C_dram_addr = (int8_t*)out +
3517:                                 (i*C_row_stride + jj) * sizeof(elem_t) +
3518:                                 r * C_row_stride * sizeof(elem_t);
3519:                             const size_t cols = J - jj < C_blocks * DIM ? J - jj : C_blocks * DIM;
3520:                             gemmini_extended_mvout(C_dram_addr, norm_C_sp_addr, cols, 1);
3521:                         }
3522:                     }
3523:                 }
3524:             }
3525:         }
3526: 
3527:     }
3528: #else
3529:     printf("Normalizations not supported in this Gemmini config\n");
3530:     exit(1);
3531: #endif
3532: }
3533: 
3534: static void tiled_norm(const size_t I, const size_t J,
3535:         const size_t tile_I, const size_t tile_J,
3536:         const acc_t * in,
3537:         elem_t * out,
3538:         const acc_scale_t C_scale,
3539:         int act,
3540:         enum tiled_matmul_type_t norm_type) {
3541: 
3542:     gemmini_extended_config_st(J * sizeof(elem_t), act & 3, C_scale);
3543:     gemmini_config_ex(WS, 0, 0); // TODO is this actually required?
3544: 
3545:     gemmini_extended4_config_ld(J * sizeof(acc_t), MVIN_SCALE_IDENTITY, false, DIM, 0);
3546:     gemmini_extended4_config_ld(J * sizeof(acc_t), MVIN_SCALE_IDENTITY, false, DIM, 1);
3547: 
3548:     if (act == SOFTMAX) {
3549:         const scale_t a = 0.3585;
3550:         const scale_t b = 1.353;
3551:         const scale_t c = 0.344;
3552: 
3553:         // TODO let bert-scale be set by the programmer
3554:         acc_scale_t bert_scale = 0.05;
3555:         const acc_t qln2 = (int) (0.693147 / bert_scale);
3556:         const acc_t qln2_inv = 65536 / qln2;
3557:         const acc_t qb = b / bert_scale;
3558:         const acc_t qc = c / (a*bert_scale*bert_scale);
3559: 
3560:         gemmini_config_norm(qln2, 0, 0, 1, 0, qb, qc);
3561:         gemmini_config_norm(qln2_inv, 1, 0, 1, 0, qb, qc);
3562:     }
3563: 
3564:     for (size_t i = 0; i < I; i += tile_I) {
3565:         for (size_t j = 0; j < J; j += tile_J) {
3566:             const size_t I_tile = i + tile_I <= I ? tile_I : I - i;
3567:             const size_t J_tile = j + tile_J <= J ? tile_J : J - j;
3568: 
3569:             const acc_t * in_ = in + i * J + j;
3570:             elem_t * out_ = out + i * J + j;
3571: 
3572:             sp_tiled_norm(I_tile, J_tile,
3573:                     in_, out_,
3574:                     J, J,
3575:                     act);
3576:         }
3577:     }
3578: 
3579:     gemmini_fence();
3580: }
3581: 
3582: _STATIC void tiled_norm_auto(const size_t I, const size_t J,
3583:         const acc_t * in,
3584:         elem_t * out,
3585:         const acc_scale_t C_scale,
3586:         int act,
3587:         enum tiled_matmul_type_t norm_type) {
3588: 
3589:     size_t tile_I = I, tile_J = J;
3590:     size_t total_acc_rows = (tile_I / DIM + (tile_I % DIM != 0))*DIM * (tile_J / DIM + (tile_J % DIM != 0));
3591: 
3592:     while (total_acc_rows > ACC_ROWS) {
3593:         if (tile_I > 1) {
3594:             tile_I--;
3595:         } else {
3596:             // TODO we should be able to tile over J as well to avoid this issue
3597:             printf("Can't fit pre-normalized tensor into accumulator");
3598:             exit(1);
3599:         }
3600: 
3601:         total_acc_rows = (tile_I / DIM + (tile_I % DIM != 0))*DIM * (tile_J / DIM + (tile_J % DIM != 0));
3602:     }
3603: 
3604:     if (norm_type) {
3605:       tiled_norm(I, J, tile_I, tile_J,
3606:             in, out,
3607:             C_scale, act, norm_type);
3608:     } else {
3609:       printf("Unsupported type\n");
3610:       exit(1);
3611:     }
3612: }
